const APP_HTML="<!doctype html>\n<html lang=\"sk\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<title>Tesla SK – Navigácia</title>\n<meta name=\"theme-color\" content=\"#111318\">\n<meta name=\"apple-mobile-web-app-title\" content=\"Tesla SK\">\n<meta name=\"application-name\" content=\"Tesla SK\">\n<meta name=\"description\" content=\"Tesla SK – navigácia, nabíjačky a hudba\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32.png?v=tw3\">\n<link rel=\"apple-touch-icon\" sizes=\"180x180\" href=\"/apple-touch-icon.png?v=tw3\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:site_name\" content=\"Tesla SK\">\n<meta property=\"og:title\" content=\"Tesla SK – Navigácia\">\n<meta property=\"og:description\" content=\"Navigácia, nabíjačky a hudba pre Tesla prehliadač\">\n<meta property=\"og:url\" content=\"https://tesla-sk.vercel.app/\">\n<meta property=\"og:image\" content=\"https://tesla-sk.vercel.app/apple-touch-icon.png?v=tw3\">\n<meta property=\"og:image:type\" content=\"image/png\">\n<meta property=\"og:image:width\" content=\"512\">\n<meta property=\"og:image:height\" content=\"512\">\n<meta name=\"twitter:card\" content=\"summary\">\n<meta name=\"twitter:title\" content=\"Tesla SK – Navigácia\">\n<meta name=\"twitter:image\" content=\"https://tesla-sk.vercel.app/apple-touch-icon.png?v=tw3\">\\n\n\n\n\n\\n\n\n\n\n\n<link rel=\"stylesheet\" href=\"https://tesla-hotspotnav-sk-v2.onrender.com/maplibre-gl.css\">\n<link rel=\"stylesheet\" href=\"https://tesla-hotspotnav-sk-v2.onrender.com/leaflet.css\">\n<style>\n/* The car browser has no Armenian or Cyrillic font, so names in those scripts showed as boxes.\n   These subsets only cover those scripts (unicode-range); Latin text keeps the system font. */\n@font-face{font-family:\"Noto Sans Armenian\";font-style:normal;font-weight:400 700;font-display:swap;\n  src:url(https://tesla-hotspotnav-sk-v2.onrender.com/fonts/noto-sans-armenian.woff2) format(\"woff2\");unicode-range:U+0308,U+0530-058F,U+2010,U+2024,U+25CC,U+FB13-FB17}\n@font-face{font-family:\"Noto Sans Cyr\";font-style:normal;font-weight:400 700;font-display:swap;\n  src:url(https://tesla-hotspotnav-sk-v2.onrender.com/fonts/noto-sans-cyrillic.woff2) format(\"woff2\");unicode-range:U+0301,U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116}\n:root{\n  /* UI scale for everything drawn over the map; the menu's Text size changes it. */\n  --ui:.8;\n  --bg:#0d1015;--panel:rgba(19,23,30,.94);--line:#2a313c;--ink:#f2f4f7;--quiet:#9aa4b2;\n  --accent:#3e8bff;--ok:#2fbf71;--warn:#f5a524;--bad:#ff5a5f;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%;background:var(--bg);color:var(--ink);overflow:hidden;\n  font:18px/1.3 \"Noto Sans Armenian\",\"Noto Sans Cyr\",system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif;-webkit-user-select:none;user-select:none;\n  -webkit-tap-highlight-color:transparent}\n#map{position:absolute;inset:0;background:var(--bg)}\n.leaflet-container{background:var(--bg);font:inherit}\n.dark-tiles{filter:invert(1) hue-rotate(180deg) brightness(.85) contrast(.85) saturate(.5)}\n.leaflet-control-attribution{background:rgba(13,16,21,.7)!important;color:var(--quiet)!important;font-size:11px}\n.leaflet-control-attribution a{color:var(--quiet)!important}\n.leaflet-popup-content-wrapper,.leaflet-popup-tip{background:var(--panel);color:var(--ink)}\n.maplibregl-popup-content{background:var(--panel);color:var(--ink);border-radius:14px;padding:10px}\n.maplibregl-popup-tip{border-top-color:var(--panel)!important;border-bottom-color:var(--panel)!important}\n.maplibregl-ctrl-attrib{background:rgba(13,16,21,.7)!important;color:var(--quiet)!important;font-size:11px}\n.maplibregl-ctrl-attrib a{color:var(--quiet)!important}\n.maplibregl-ctrl-attrib-button{filter:invert(1)}\n.panel{background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:0 10px 32px rgba(0,0,0,.5)}\nbutton{font:inherit;color:inherit;background:#232a35;border:1px solid var(--line);border-radius:14px;\n  min-height:60px;padding:0 22px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:10px}\nbutton:active{filter:brightness(1.3)}\nbutton.primary{background:var(--accent);border-color:var(--accent);color:#fff;font-weight:600}\nbutton.danger{background:#3b1c20;border-color:#5b2a2f;color:#ffc2c4;font-weight:600}\nbutton svg{width:28px;height:28px}\n.hidden{display:none!important}\n.left{position:absolute;left:16px;width:min(480px,calc(100% - 120px));z-index:1000}\n.left,#fabs,#menu,#pairBox,#mirrorBar,#mirrorHint{zoom:var(--ui)}\n#status,#toast{font-size:15px}\n/* While navigating, the charger list opens below the turn banner instead of under it. */\nbody.navigating #chargerPanel{top:190px}\n\n/* search */\n#search{top:16px;overflow:hidden}\n#chargerPanel{top:16px;bottom:16px;display:flex;flex-direction:column;overflow-y:auto;overflow-x:hidden;z-index:1400;-webkit-overflow-scrolling:touch;overscroll-behavior:contain}\n#chargerPanel header{display:flex;align-items:center;gap:12px;padding:14px 14px 10px 20px;position:sticky;top:0;z-index:5;background:var(--panel)}\n#chargerPanel header b{flex:1;font-size:22px}\n#chargerPanel header button{min-height:48px;padding:0 16px;position:relative;z-index:2;pointer-events:auto}\\n#chargerClose{min-width:64px;min-height:56px!important;font-size:26px;touch-action:manipulation}\n.chips{display:flex;flex-wrap:wrap;gap:8px;padding:0 20px 12px}\n.chip{min-height:44px;padding:0 16px;border-radius:999px;font-size:16px;background:#1b212a}\n.chip.on{background:var(--accent);border-color:var(--accent);color:#fff;font-weight:600}\n.chipLabel{width:100%;color:var(--quiet);font-size:14px;margin:2px 0 -2px}\n#chargerList{overflow:visible;border-top:1px solid var(--line);flex:none;min-height:0}\n#chargerList .res b{display:flex;gap:8px;align-items:center}\n.res .conn,.conn{display:inline-block;font-size:13px;font-weight:600;padding:2px 8px;border-radius:6px;background:#1f3a2a;color:#8ee6b0;margin:6px 6px 0 0}\n.conn.unknown{background:#2a2f38;color:var(--quiet)}\n.charger-power-icon{background:transparent!important;border:0!important}\n.waze-alert-icon{background:transparent!important;border:0!important}\n.waze-alert-bubble{\n  width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;\n  background:#1f2733;border:2px solid #fff;color:#fff;font:700 18px/1 system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  box-shadow:0 2px 7px rgba(0,0,0,.55)\n}\n.waze-alert-bubble.police{background:#2463eb}\n.waze-alert-bubble.jam{background:#d97706}\n.waze-alert-bubble.accident{background:#dc2626}\n.waze-alert-bubble.closure{background:#991b1b}\n.waze-alert-bubble.camera{background:#7c3aed}\n.waze-alert-bubble.hazard{background:#ca8a04}\n.charger-power-bubble{\n  width:34px;height:34px;border-radius:50%;\n  display:flex;align-items:center;justify-content:center;\n  background:#2fbf71;color:#fff;border:2px solid #fff;\n  font:700 11px/1 system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  box-shadow:0 1px 4px rgba(0,0,0,.45)\n}\n#searchRow{display:flex;align-items:center}\n#quickPlaces{display:flex;gap:8px;padding:0 14px 12px 14px}\n#quickPlaces button{flex:1;min-height:46px;border-radius:14px;background:#1b212a;font-weight:650;justify-content:center}\n#quickPlaces button.unset{color:var(--quiet)}\n#quickPlaces button svg{width:22px;height:22px;margin-right:7px;vertical-align:-5px}\n#pairQr{width:220px;height:220px;display:block;margin:16px auto 10px;background:#fff;border-radius:14px;padding:8px}\n#pairDisplay{font:800 32px/1 ui-monospace,Menlo,monospace;letter-spacing:4px;text-align:center;margin:8px 0}\n#pairHint{text-align:center;color:var(--quiet);font-size:15px;line-height:1.4}\n#pairBox .pairActions{display:flex;gap:10px;justify-content:center;margin-top:16px}\n#pairBox .pairActions button{min-height:48px}\n#searchRow svg{width:28px;height:28px;margin-left:20px;color:var(--quiet);flex:none}\n#q{flex:1;min-width:0;height:68px;border:0;background:transparent;color:var(--ink);font:inherit;font-size:22px;padding:0 16px;outline:none}\ninput[type=search]::-webkit-search-cancel-button{display:none}\n#clearQ{min-height:48px;margin-right:10px;padding:0 14px;background:transparent;border:0;color:var(--quiet)}\n#results{max-height:62vh;overflow:auto;border-top:1px solid var(--line)}\n#results:empty{display:none}\n.res{padding:16px 20px;border-bottom:1px solid var(--line);cursor:pointer}\n.res:last-child{border-bottom:0}\n.res:active{background:#232a35}\n.res b{display:block;font-weight:600;font-size:20px}\n.res span{display:block;color:var(--quiet);font-size:15px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.res.note{color:var(--quiet);cursor:default}\n\n/* maneuver banner */\n#banner{top:16px;display:flex;gap:18px;align-items:center;padding:18px 22px;background:#15345f;border-color:#24508c}\n#bIcon{width:84px;height:84px;flex:none;color:#fff}\n#bDist{font-size:40px;font-weight:700;line-height:1}\n#bText{font-size:22px;margin-top:6px;color:#dbe7ff}\n#bThen{margin-top:10px;font-size:16px;color:#a9c4ef;display:flex;align-items:center;gap:8px}\n#bThen svg{width:26px;height:26px}\n\n/* trip bar */\n#trip{bottom:28px;display:flex;align-items:center;gap:14px;padding:16px 14px 12px 22px;overflow:hidden}\n#trip:before{content:\"\";position:absolute;left:0;right:0;top:0;height:4px;background:#27313e}\n#tripProgress{position:absolute;left:0;top:0;height:4px;width:0;background:var(--accent);transition:width .45s linear;z-index:2}\n#tArrive{font-size:34px;font-weight:700;line-height:1}\n#tRest{color:var(--quiet);font-size:18px;margin-top:3px;white-space:nowrap}\n#tDest{margin-top:4px;font-size:clamp(13px,1.7vw,17px);font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;color:#dfe6ef}\n#trip .grow{flex:1;min-width:0}\n#overview{display:none!important}\n\n/* right column */\n#fabs{position:absolute;top:16px;right:16px;z-index:1000;display:flex;flex-direction:column;gap:12px;align-items:flex-end}\n#fabs button{width:76px;height:76px;padding:0;border-radius:20px;background:var(--panel)}\n#fabs button.label{width:auto;padding:0 20px;font-size:17px;font-weight:600}\n#northBtn{font-weight:800;font-size:15px;flex-direction:column;gap:2px}\n#northBtn svg{width:30px;height:30px;transition:transform .3s}\n#speed{width:88px;height:88px;border-radius:50%;background:var(--panel);border:1px solid var(--line);\n  display:flex;flex-direction:column;align-items:center;justify-content:center}\n#speed b{font-size:34px;line-height:1}\n#speed span{font-size:13px;color:var(--quiet)}\n#menu{position:absolute;top:16px;right:108px;z-index:1001;padding:10px;display:flex;flex-direction:column;gap:8px;min-width:280px}\n#menu button{justify-content:flex-start;width:100%}\n#voiceVolumeBox{padding:10px 12px 12px;border:1px solid var(--line);border-radius:14px;background:#171c24}\n#voiceVolumeLabel{display:flex;justify-content:space-between;gap:16px;align-items:center;font-size:16px;margin-bottom:8px}\n#voiceVolumeLabel b{font-size:17px}\n#voiceVolume{width:100%;height:30px;accent-color:var(--accent);touch-action:pan-x}\n\n/* status pill + toast */\n#status{position:absolute;left:50%;transform:translateX(-50%);bottom:28px;z-index:999;padding:10px 18px;border-radius:999px;font-size:16px;white-space:nowrap}\n#status.warn{color:var(--warn)} #status.bad{color:var(--bad)} #status.ok{color:var(--ok)}\nbody.navigating #status{bottom:130px}\n#toast{position:absolute;left:50%;top:24px;transform:translateX(-50%);z-index:3000;padding:14px 22px;font-size:20px;\n  transition:opacity .3s;pointer-events:none}\n\n/* car marker */\n.car{width:52px;height:52px;display:grid;place-items:center;transition:transform .8s ease-out}\n.car svg{width:52px;height:52px;filter:drop-shadow(0 2px 6px rgba(0,0,0,.6))}\n/* MapLibre positions markers with transform itself; animating it makes the car lag behind. */\n.car.gl{transition:none}\n.dest{width:40px;height:40px}\n\n/* mirror mode */\n#mirror{position:fixed;inset:0;z-index:2000;background:#000;display:flex;align-items:center;justify-content:center}\n#mirrorCanvas{width:100%;height:100%;display:block}\n#mirrorBar{position:absolute;top:16px;right:16px;display:flex;gap:10px;transition:opacity .4s}\n#mirrorBar button{background:var(--panel);font-weight:600}\n#mirror.idle #mirrorBar{opacity:0;pointer-events:none}\n#mirrorHint{position:absolute;max-width:560px;padding:28px;text-align:center;font-size:22px}\n#mirrorHint p{color:var(--quiet);font-size:18px;margin:12px 0 0}\n#pair{position:fixed;inset:0;z-index:2500;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center}\n#pairBox{width:min(560px,calc(100% - 32px));padding:28px}\n#pairBox h2{margin:0 0 8px;font-size:26px}\n#pairBox p{color:var(--quiet);margin:0 0 18px}\n#pairCode{width:100%;height:72px;font:700 34px/1 ui-monospace,Menlo,monospace;letter-spacing:6px;text-transform:uppercase;text-align:center;\n  background:#0d1015;color:var(--ink);border:1px solid var(--line);border-radius:14px;outline:none}\n#pairBox .row{display:flex;gap:12px;justify-content:flex-end;margin-top:18px}\n\n/* Hudba: prehrávač ostáva načítaný aj po minimalizovaní */\n#musicOverlay{\n  position:fixed;inset:0;z-index:2300;background:#000;\n  display:flex;flex-direction:column;\n  transform:translateY(105%);\n  transition:transform .28s ease;\n  pointer-events:none;\n  will-change:transform\n}\n#musicOverlay.open{transform:translateY(0);pointer-events:auto}\n#musicGrab{\n  height:38px;flex:none;background:rgba(10,12,16,.96);\n  display:flex;align-items:center;justify-content:center;\n  touch-action:none;cursor:grab\n}\n#musicGrab:after{\n  content:\"\";width:72px;height:6px;border-radius:999px;\n  background:rgba(255,255,255,.5)\n}\n#musicFrame{border:0;width:100%;flex:1;background:#000}\n#musicBtn svg{width:31px;height:31px}\n\n/* Waze nad navigáciou: rovnaké správanie ako Music, iframe ostáva načítaný */\n#wazeOverlay{\n  position:fixed;inset:0;z-index:2310;background:#000;\n  display:flex;flex-direction:column;\n  transform:translateY(105%);\n  transition:transform .28s ease;\n  pointer-events:none;\n  will-change:transform\n}\n#wazeOverlay.open{transform:translateY(0);pointer-events:auto}\n#wazeGrab{\n  height:38px;flex:none;background:rgba(10,12,16,.96);\n  display:flex;align-items:center;justify-content:center;\n  touch-action:none;cursor:grab\n}\n#wazeGrab:after{\n  content:\"\";width:72px;height:6px;border-radius:999px;\n  background:rgba(255,255,255,.5)\n}\n#wazeFrame{border:0;width:100%;flex:1;background:#000}\n#wazeBtn{font-size:17px;font-weight:800}\n#wazeBtn svg{width:34px;height:34px}\n\n.liveStatus{margin:8px 0 10px;padding:8px 10px;border-radius:10px;background:#182129;font-size:14px}\n.liveStatus .ok{color:#63d69a}.liveStatus .busy{color:#ffcc66}.liveStatus .bad{color:#ff7a7a}.liveStatus .muted{color:var(--quiet)}\n</style>\n</head>\n<body>\n<div id=\"map\"></div>\n\n<div id=\"search\" class=\"panel left\">\n  <div id=\"searchRow\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M20 20l-4-4\"/></svg>\n    <!-- type=text, not search: the car shows its web-address keyboard (\".com\", no space bar) for search fields. -->\n    <input id=\"q\" type=\"text\" enterkeyhint=\"search\" placeholder=\"Kam chcete ísť?\" autocomplete=\"off\" autocorrect=\"off\" spellcheck=\"false\">\n    <button id=\"clearQ\" class=\"hidden\" aria-label=\"Vymazať\">✕</button>\n  </div>\n  <div id=\"quickPlaces\">\n    <button id=\"homeBtn\" type=\"button\" title=\"Domov · podržaním zmeniť\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 11l9-8 9 8\"/><path d=\"M5 10v10h14V10\"/><path d=\"M9 20v-6h6v6\"/></svg>Domov\n    </button>\n    <button id=\"workBtn\" type=\"button\" title=\"Práca · podržaním zmeniť\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"4\" y=\"7\" width=\"16\" height=\"13\" rx=\"2\"/><path d=\"M9 7V4h6v3\"/><path d=\"M4 12h16\"/></svg>Práca\n    </button>\n  </div>\n  <div id=\"results\"></div>\n</div>\n\n<div id=\"chargerPanel\" class=\"panel left hidden\">\n  <header><b>Nabíjačky EV</b><button id=\"chargerMapBtn\"></button><button id=\"chargerClose\" aria-label=\"Zavrieť\">✕</button></header>\n  <div class=\"chips\" id=\"connChips\"></div>\n  <div class=\"chips\" id=\"powerChips\"></div>\n  <div class=\"chips\" id=\"opChips\"></div>\n  <div id=\"chargerList\"></div>\n  <div style=\"padding:8px 20px;font-size:12px;color:var(--quiet);border-top:1px solid var(--line)\">Zdroj nabíjačiek: Open Charge Map</div>\n</div>\n\n<div id=\"banner\" class=\"panel left hidden\">\n  <div id=\"bIcon\"></div>\n  <div style=\"min-width:0\">\n    <div id=\"bDist\"></div>\n    <div id=\"bText\"></div>\n    <div id=\"bThen\" class=\"hidden\"></div>\n  </div>\n</div>\n\n<div id=\"trip\" class=\"panel left hidden\">\n  <div id=\"tripProgress\"></div>\n  <div class=\"grow\">\n    <div id=\"tArrive\"></div>\n    <div id=\"tRest\"></div>\n    <div id=\"tDest\"></div>\n  </div>\n  <button id=\"overview\" aria-label=\"Prehľad trasy\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M9 4L3 6v14l6-2 6 2 6-2V4l-6 2-6-2zM9 4v14M15 6v14\"/></svg>\n  </button>\n  <button id=\"end\" class=\"danger\">Ukončiť</button>\n</div>\n\n<div id=\"fabs\">\n  <div id=\"speed\" class=\"hidden\"><b>0</b><span>km/h</span></div>\n  <button id=\"northBtn\" class=\"hidden\" aria-label=\"Smer jazdy alebo sever hore\"></button>\n  <button id=\"recenter\" class=\"hidden\" aria-label=\"Vycentrovať\">\n    <svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M12 2l7 19-7-4-7 4z\"/></svg>\n  </button>\n  <button id=\"chargersFab\" class=\"label\">⚡ Nabíjačky</button>\n  <button id=\"mirrorBtn\" class=\"label\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"7\" y=\"2\" width=\"10\" height=\"20\" rx=\"3\"/><path d=\"M10 18h4\"/><path d=\"M4 9h3M17 9h3\"/></svg>\n    Prepojiť mobil\n  </button>\n  <button id=\"menuBtn\" aria-label=\"Menu\">\n    <svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><circle cx=\"5\" cy=\"12\" r=\"2.2\"/><circle cx=\"12\" cy=\"12\" r=\"2.2\"/><circle cx=\"19\" cy=\"12\" r=\"2.2\"/></svg>\n  </button>\n  <button id=\"musicBtn\" aria-label=\"Hudba\" title=\"Hudba\">\n    <svg viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\">\n      <path d=\"M9 18V5l11-2v13.2a3.5 3.5 0 1 1-2-3.16V7.4L11 8.7V18a3.5 3.5 0 1 1-2-3.16z\"/>\n    </svg>\n  </button>\n</div>\n\n\n<div id=\"musicOverlay\" aria-hidden=\"true\">\n  <div id=\"musicGrab\" aria-label=\"Potiahnutím nadol skryjete prehrávač\"></div>\n  <iframe\n    id=\"musicFrame\"\n    title=\"Hudba\"\n    allow=\"autoplay; encrypted-media; picture-in-picture\"\n    src=\"about:blank\"></iframe>\n</div>\n\n<div id=\"wazeOverlay\" aria-hidden=\"true\">\n  <div id=\"wazeGrab\" aria-label=\"Potiahnutím nadol skryjete Waze\"></div>\n  <iframe\n    id=\"wazeFrame\"\n    title=\"Waze\"\n    allow=\"geolocation; autoplay\"\n    src=\"about:blank\"></iframe>\n</div>\n\n<div id=\"menu\" class=\"panel hidden\">\n  <button id=\"voiceBtn\"></button>\n  <div id=\"voiceVolumeBox\">\n    <div id=\"voiceVolumeLabel\"><span>🔉 Hlasitosť navigácie</span><b id=\"voiceVolumeValue\">70 %</b></div>\n    <input id=\"voiceVolume\" type=\"range\" min=\"20\" max=\"100\" step=\"10\" value=\"70\" aria-label=\"Hlasitosť navigácie\">\n  </div>\n  <button id=\"testVoice\">Test hlasu</button>\n  <button id=\"styleBtn\"></button>\n  <button id=\"sizeBtn\"></button>\n  <button id=\"engineBtn\"></button>\n\n  <button id=\"simBtn\">Simulovať jazdu</button>\n  <button id=\"pairBtn\">📱  Prepojiť mobil</button>\n</div>\n\n<div id=\"status\" class=\"panel hidden\"></div>\n<div id=\"toast\" class=\"panel\" style=\"opacity:0\"></div>\n\n<div id=\"mirror\" class=\"hidden\">\n  <canvas id=\"mirrorCanvas\"></canvas>\n  <div id=\"mirrorHint\" class=\"panel\">\n    <span id=\"mirrorHintTitle\">Pripájam…</span>\n    <p>Na iPhone otvor HotspotNav a klepni na <b>Spustiť vysielanie</b>, potom prepni do Waze, Google Maps alebo inej navigácie.</p>\n  </div>\n  <div id=\"mirrorBar\">\n    <button id=\"fitBtn\"></button>\n    <button id=\"fullBtn\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5\"/></svg>\n      Celá obrazovka\n    </button>\n    <button id=\"mirrorBack\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M9 4L3 6v14l6-2 6 2 6-2V4l-6 2-6-2zM9 4v14M15 6v14\"/></svg>\n      Map\n    </button>\n  </div>\n</div>\n\n<div id=\"pair\" class=\"hidden\">\n  <div id=\"pairBox\" class=\"panel\">\n    <h2>Prepojiť mobil</h2>\n    <p id=\"pairHint\">Naskenuj QR kód mobilom. Na mobile potom vyhľadaj alebo označ cieľ a odošli ho do Tesly.</p>\n    <img id=\"pairQr\" alt=\"QR kód pre mobil\">\n    <div id=\"pairDisplay\"></div>\n    <div class=\"pairActions\"><button id=\"pairNew\">Nový kód</button><button id=\"pairCancel\" class=\"primary\">Hotovo</button></div>\n  </div>\n</div>\n\n<script src=\"https://tesla-hotspotnav-sk-v2.onrender.com/maplibre-gl.js\"></script>\n<script src=\"https://tesla-hotspotnav-sk-v2.onrender.com/leaflet.js\"></script>\n<script>\n(() => {\n'use strict';\n\n// ---------------------------------------------------------------- helpers\nconst $ = id => document.getElementById(id);\nconst show = (el, on) => el.classList.toggle('hidden', !on);\nconst store = {\n  get(k, d) { try { const v = localStorage.getItem('tn.' + k); return v == null ? d : JSON.parse(v); } catch { return d; } },\n  set(k, v) { try { localStorage.setItem('tn.' + k, JSON.stringify(v)); } catch {} },\n};\nasync function fetchT(url, ms) {\n  const ctl = new AbortController();\n  const t = setTimeout(() => ctl.abort(), ms);\n  try { return await fetch(url, { signal: ctl.signal, cache: 'no-store' }); } finally { clearTimeout(t); }\n}\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nlet toastTimer;\nfunction toast(msg, ms = 3000) {\n  const el = $('toast');\n  el.textContent = msg; el.style.opacity = 1;\n  clearTimeout(toastTimer); toastTimer = setTimeout(() => el.style.opacity = 0, ms);\n}\nfunction setStatus(msg, kind) {\n  const el = $('status');\n  show(el, !!msg); el.textContent = msg || ''; el.className = 'panel ' + (kind || '') + (msg ? '' : ' hidden');\n}\n\n// ---------------------------------------------------------------- geo\nconst R = 6371008.8, rad = d => d * Math.PI / 180, deg = r => r * 180 / Math.PI;\nfunction dist(a, b) {\n  const dLat = rad(b.lat - a.lat), dLng = rad(b.lng - a.lng);\n  const s = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;\n  return 2 * R * Math.asin(Math.sqrt(s));\n}\nfunction bearing(a, b) {\n  const y = Math.sin(rad(b.lng - a.lng)) * Math.cos(rad(b.lat));\n  const x = Math.cos(rad(a.lat)) * Math.sin(rad(b.lat)) - Math.sin(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.cos(rad(b.lng - a.lng));\n  return (deg(Math.atan2(y, x)) + 360) % 360;\n}\n/** Nearest point on segment a–b to p, in local metres: {t, d}. */\nfunction projSeg(p, a, b) {\n  const my = R * Math.PI / 180, mx = my * Math.cos(rad(p.lat));\n  const ax = (a.lng - p.lng) * mx, ay = (a.lat - p.lat) * my, bx = (b.lng - p.lng) * mx, by = (b.lat - p.lat) * my;\n  const dx = bx - ax, dy = by - ay, l2 = dx * dx + dy * dy;\n  const t = l2 ? Math.max(0, Math.min(1, -(ax * dx + ay * dy) / l2)) : 0;\n  return { t, d: Math.hypot(ax + t * dx, ay + t * dy) };\n}\nfunction fmtDist(m) {\n  if (m >= 10000) return Math.round(m / 1000) + ' km';\n  if (m >= 1000) return (m / 1000).toFixed(1) + ' km';\n  if (m >= 100) return Math.round(m / 50) * 50 + ' m';\n  return Math.max(0, Math.round(m / 10) * 10) + ' m';\n}\nfunction spokenDist(m) {\n  if (m >= 1000) {\n    const km = Math.round(m / 100) / 10;\n    return km === 1 ? '1 kilometer' : km + ' kilometra';\n  }\n  return Math.max(50, Math.round(m / 50) * 50) + ' metrov';\n}\nfunction fmtDuration(s) {\n  const min = Math.max(1, Math.round(s / 60));\n  return min < 60 ? min + ' min' : Math.floor(min / 60) + ' h ' + (min % 60) + ' min';\n}\n\n// ---------------------------------------------------------------- map\n// Two engines behind one small interface (M): a vector map drawn with MapLibre (sharp at\n// every zoom, can rotate heading-up and tilt), and the older Leaflet raster map as a\n// fallback for browsers without WebGL or when chosen in the menu.\nconst params = new URLSearchParams(location.search);\nconst saved = store.get('view', { lat: 20, lng: 0, z: 3 });\nconst CAR_SVG = '<svg viewBox=\"0 0 52 52\"><circle cx=\"26\" cy=\"26\" r=\"22\" fill=\"#3e8bff\" stroke=\"#fff\" stroke-width=\"4\"/><path d=\"M26 12l10 24-10-6-10 6z\" fill=\"#fff\"/></svg>';\nconst DEST_SVG = '<svg class=\"dest\" viewBox=\"0 0 40 40\"><path d=\"M20 38s13-13 13-22a13 13 0 0 0-26 0c0 9 13 22 13 22z\" fill=\"#ff5a5f\" stroke=\"#fff\" stroke-width=\"2.5\"/><circle cx=\"20\" cy=\"16\" r=\"5\" fill=\"#fff\"/></svg>';\n\nfunction hasWebGL() {\n  try { const c = document.createElement('canvas'); return !!(c.getContext('webgl2') || c.getContext('webgl')); }\n  catch { return false; }\n}\nconst engine = store.get('engine', 'vector') === 'vector' && window.maplibregl && hasWebGL() ? 'vector' : 'classic';\n\n/** A circle of `r` metres around p as a GeoJSON ring (for the GPS accuracy halo). */\nfunction circleRing(p, r) {\n  const pts = [], dLat = r / 111320, dLng = r / (111320 * Math.cos(rad(p.lat)));\n  for (let i = 0; i <= 48; i++) { const a = i / 48 * 2 * Math.PI; pts.push([p.lng + dLng * Math.cos(a), p.lat + dLat * Math.sin(a)]); }\n  return pts;\n}\n\nfunction vectorMap() {\n  const STYLES = {\n    night: { name: 'Noc', url: 'https://tiles.openfreemap.org/styles/dark' },\n    day: { name: 'Deň', url: 'https://tiles.openfreemap.org/styles/liberty' },\n  };\n  let styleKey = STYLES[store.get('vstyle')] ? store.get('vstyle') : 'night';\n  const map = new maplibregl.Map({\n    container: 'map', style: STYLES[styleKey].url, center: [saved.lng, saved.lat], zoom: saved.z,\n    attributionControl: { compact: true }, dragRotate: true, pitchWithRotate: true, maxPitch: 60,\n  });\n  const empty = { type: 'FeatureCollection', features: [] };\n  let routeData = empty, accData = empty, wazeJamData = empty, wazeAlertData = empty, onWazeAlert = null;\n\n  // Route and GPS halo live in the style, so they're re-added whenever the style changes.\n  function addOverlays() {\n    if (map.getSource('route')) return;\n    map.addSource('route', { type: 'geojson', data: routeData });\n    map.addSource('acc', { type: 'geojson', data: accData });\n    map.addLayer({ id: 'acc', type: 'fill', source: 'acc', paint: { 'fill-color': '#3e8bff', 'fill-opacity': 0.12 } });\n    map.addLayer({ id: 'route-casing', type: 'line', source: 'route', layout: { 'line-join': 'round', 'line-cap': 'round' },\n                   paint: { 'line-color': '#0b2a57', 'line-width': ['interpolate', ['linear'], ['zoom'], 10, 7, 16, 16] } });\n    map.addLayer({ id: 'route-line', type: 'line', source: 'route', layout: { 'line-join': 'round', 'line-cap': 'round' },\n                   paint: { 'line-color': '#3e8bff', 'line-width': ['interpolate', ['linear'], ['zoom'], 10, 4, 16, 9] } });\n\n    map.addSource('waze-jams', { type: 'geojson', data: wazeJamData });\n    map.addLayer({ id: 'waze-jams', type: 'line', source: 'waze-jams',\n      layout: { 'line-join': 'round', 'line-cap': 'round' },\n      paint: {\n        'line-color': ['match', ['get','level'], 4, '#b91c1c', 3, '#ef4444', 2, '#f59e0b', 1, '#facc15', '#f59e0b'],\n        'line-width': ['interpolate', ['linear'], ['zoom'], 10, 5, 16, 10],\n        'line-opacity': .95\n      }\n    });\n\n    map.addSource('waze-alerts', { type: 'geojson', data: wazeAlertData });\n    map.addLayer({ id: 'waze-alert-circles', type: 'circle', source: 'waze-alerts',\n      paint: {\n        'circle-radius': ['interpolate', ['linear'], ['zoom'], 8, 8, 15, 15],\n        'circle-color': ['match', ['get','kind'],\n          'police','#2463eb','jam','#d97706','accident','#dc2626','closure','#991b1b','camera','#7c3aed','#ca8a04'],\n        'circle-stroke-color':'#ffffff','circle-stroke-width':2\n      }\n    });\n    map.addLayer({ id: 'waze-alert-labels', type: 'symbol', source: 'waze-alerts',\n      layout: {\n        'text-field':['get','label'],\n        'text-size':['interpolate',['linear'],['zoom'],8,10,15,17],\n        'text-allow-overlap':true,'text-ignore-placement':true\n      },\n      paint:{'text-color':'#ffffff','text-halo-color':'rgba(0,0,0,.35)','text-halo-width':1}\n    });\n\n    map.addSource('chargers', { type: 'geojson', data: chargerData });\n    map.addLayer({ id: 'chargers', type: 'circle', source: 'chargers',\n                   paint: { 'circle-radius': ['interpolate', ['linear'], ['zoom'], 8, 9, 15, 17], 'circle-color': '#2fbf71',\n                            'circle-stroke-color': '#fff', 'circle-stroke-width': 2 } });\n    map.addLayer({ id: 'charger-power-labels', type: 'symbol', source: 'chargers',\n                   layout: {\n                     'text-field': ['get', 'power'],\n                     'text-size': ['interpolate', ['linear'], ['zoom'], 8, 9, 15, 12],\n                     'text-allow-overlap': true,\n                     'text-ignore-placement': true\n                   },\n                   paint: { 'text-color': '#ffffff', 'text-halo-color': '#176b46', 'text-halo-width': 1 } });\n  }\n  let chargerData = empty, onCharger = null;\n  map.on('click', 'chargers', e => { const f = e.features[0]; if (f && onCharger) onCharger(JSON.parse(f.properties.c)); });\n  map.on('click', 'waze-alert-circles', e => { const f = e.features[0]; if (f && onWazeAlert) onWazeAlert(JSON.parse(f.properties.a)); });\n  map.on('click', 'waze-alert-labels', e => { const f = e.features[0]; if (f && onWazeAlert) onWazeAlert(JSON.parse(f.properties.a)); });\n  // OpenFreeMap's dark style is very low-contrast; on a car screen in daylight the roads vanish.\n  // Lift roads, labels and land a few steps while keeping it a night map.\n  const NIGHT = {\n    background: ['background-color', '#10141a'],\n    water: ['fill-color', '#15263a'], waterway: ['line-color', '#1d3350'],\n    landuse_residential: ['fill-color', '#13171d'], landcover_wood: ['fill-color', '#122019'], landuse_park: ['fill-color', '#122019'],\n    building: ['fill-color', '#1b212a'],\n    highway_path: ['line-color', '#2a3140'], highway_minor: ['line-color', '#3a4353'],\n    highway_major_casing: ['line-color', '#262c36'], highway_major_inner: ['line-color', '#5d6879'], highway_major_subtle: ['line-color', '#4a5465'],\n    highway_motorway_casing: ['line-color', '#3a2f1c'], highway_motorway_inner: ['line-color', '#9a7b3f'], highway_motorway_subtle: ['line-color', '#6d5a33'],\n    'aeroway-runway': ['line-color', '#2c3340'], 'aeroway-taxiway': ['line-color', '#232933'], 'aeroway-area': ['fill-color', '#161b22'],\n    railway: ['line-color', '#343a44'], railway_minor: ['line-color', '#2c323b'], railway_transit: ['line-color', '#2c323b'],\n    highway_name_other: ['text-color', '#b9c2cf'], highway_name_motorway: ['text-color', '#e0cf9f'], water_name: ['text-color', '#6f8fb5'],\n  };\n  function tuneNight() {\n    if (styleKey !== 'night') return;\n    for (const [id, [prop, value]] of Object.entries(NIGHT)) {\n      if (map.getLayer(id)) try { map.setPaintProperty(id, prop, value); } catch {}\n    }\n    for (const l of map.getStyle().layers) {\n      if (l.type !== 'symbol') continue;\n      if (l.id.startsWith('place_')) try { map.setPaintProperty(l.id, 'text-color', '#d3dae4'); } catch {}\n      try { map.setPaintProperty(l.id, 'text-halo-color', '#10141a'); map.setPaintProperty(l.id, 'text-halo-width', 1.4); } catch {}\n    }\n  }\n  // Street labels: the Latin name alone; \"ARAM STREET Արամ փողոց\" side by side is unreadable at speed.\n  function latinStreetLabels() {\n    for (const id of ['highway_name_other', 'highway_name_major', 'road_label', 'highway-name-minor', 'highway-name-major']) {\n      if (map.getLayer(id)) try {\n        map.setLayoutProperty(id, 'text-field', ['coalesce', ['get', 'name:latin'], ['get', 'name_en'], ['get', 'name']]);\n      } catch {}\n    }\n  }\n  map.on('style.load', () => { tuneNight(); latinStreetLabels(); addOverlays(); });\n\n  const carEl = document.createElement('div');\n  carEl.className = 'car gl'; carEl.innerHTML = CAR_SVG;\n  const car = new maplibregl.Marker({ element: carEl, rotationAlignment: 'map', pitchAlignment: 'map' });\n  const destEl = document.createElement('div'); destEl.innerHTML = DEST_SVG;\n  const destM = new maplibregl.Marker({ element: destEl, anchor: 'bottom' });\n  let popup = null;\n\n  // Long press (touch or mouse) → 'longpress'.\n  const handlers = {};\n  let pressTimer = null, pressAt = null;\n  const canvasEl = map.getCanvasContainer();\n  canvasEl.addEventListener('pointerdown', e => {\n    pressAt = [e.clientX, e.clientY];\n    clearTimeout(pressTimer);\n    pressTimer = setTimeout(() => {\n      const r = map.getContainer().getBoundingClientRect();\n      const ll = map.unproject([pressAt[0] - r.left, pressAt[1] - r.top]);\n      (handlers.longpress || (() => {}))({ lat: ll.lat, lng: ll.lng });\n    }, 650);\n  });\n  const cancelPress = e => {\n    if (e.type === 'pointermove' && pressAt && Math.hypot(e.clientX - pressAt[0], e.clientY - pressAt[1]) < 10) return;\n    clearTimeout(pressTimer);\n  };\n  ['pointerup', 'pointercancel', 'pointermove'].forEach(t => canvasEl.addEventListener(t, cancelPress));\n\n  return {\n    kind: 'vector', canRotate: true,\n    styleName: () => STYLES[styleKey].name,\n    nextStyle() { styleKey = styleKey === 'night' ? 'day' : 'night'; store.set('vstyle', styleKey); map.setStyle(STYLES[styleKey].url); },\n    center() { const c = map.getCenter(); return { lat: c.lat, lng: c.lng }; },\n    zoom: () => map.getZoom(),\n    bearing: () => map.getBearing(),\n    setZoom(z) { map.jumpTo({ zoom: z }); },\n    /** Instant move. `ahead` shifts the car towards the bottom of the screen (0..0.5). */\n    jump(p, { zoom, bearing = 0, pitch = 0, ahead = 0 } = {}) {\n      const h = map.getContainer().clientHeight;\n      map.jumpTo({ center: [p.lng, p.lat], zoom: zoom ?? map.getZoom(), bearing, pitch,\n                   padding: { top: h * ahead * 2, bottom: 0, left: 0, right: 0 } });\n    },\n    /** North-up follow with the view pushed ahead of the car along `course`. */\n    jumpAhead(p, course, frac) {\n      const c = map.getContainer(), a = rad(course);\n      map.jumpTo({ center: [p.lng, p.lat], bearing: 0, pitch: 0, padding: { top: 0, bottom: 0, left: 0, right: 0 } });\n      const pt = map.project([p.lng, p.lat]);\n      const ll = map.unproject([pt.x + Math.sin(a) * c.clientWidth * frac, pt.y - Math.cos(a) * c.clientHeight * frac]);\n      map.jumpTo({ center: ll });\n    },\n    fit(points, pad) {\n      const b = new maplibregl.LngLatBounds();\n      points.forEach(p => b.extend([p.lng, p.lat]));\n      map.fitBounds(b, { padding: pad, maxZoom: 17, bearing: 0, pitch: 0, duration: 800 });\n    },\n    setCar(p, heading) { car.setLngLat([p.lng, p.lat]).setRotation(heading); if (!car._map) car.addTo(map); },\n    setAcc(p, r) { accData = { type: 'Feature', geometry: { type: 'Polygon', coordinates: [circleRing(p, r)] } }; map.getSource('acc')?.setData(accData); },\n    setRoute(points) {\n      routeData = { type: 'Feature', geometry: { type: 'LineString', coordinates: points.map(p => [p.lng, p.lat]) } };\n      map.getSource('route')?.setData(routeData);\n    },\n    clearRoute() { routeData = empty; map.getSource('route')?.setData(empty); },\n    setChargers(list, onTap) {\n      onCharger = onTap;\n      chargerData = { type: 'FeatureCollection', features: list.map(c => {\n        const kw = Math.round(parseFloat(c.p) || 0);\n        return { type: 'Feature',\n          properties: { c: JSON.stringify(c), power: kw ? String(kw) : '?' },\n          geometry: { type: 'Point', coordinates: [c.lng, c.lat] } };\n      }) };\n      map.getSource('chargers')?.setData(chargerData);\n    },\n    bounds() {\n      const b = map.getBounds();\n      return { top:b.getNorth(), bottom:b.getSouth(), left:b.getWest(), right:b.getEast() };\n    },\n    setWaze(alerts, jams, onTap) {\n      onWazeAlert = onTap;\n      wazeJamData = { type:'FeatureCollection', features:(jams||[]).map(j => ({\n        type:'Feature', properties:{ level:Number(j.level)||0, speedKMH:Number(j.speedKMH)||0, length:Number(j.length)||0 },\n        geometry:{ type:'LineString', coordinates:(j.line||[]).map(p => [Number(p.lng),Number(p.lat)]).filter(c => Number.isFinite(c[0])&&Number.isFinite(c[1])) }\n      })).filter(f => f.geometry.coordinates.length > 1) };\n      wazeAlertData = { type:'FeatureCollection', features:(alerts||[]).map(a => {\n        const v = wazeAlertVisual(a.type);\n        return { type:'Feature', properties:{ a:JSON.stringify(a), kind:v.kind, label:v.label },\n          geometry:{ type:'Point', coordinates:[Number(a.lng),Number(a.lat)] } };\n      }).filter(f => Number.isFinite(f.geometry.coordinates[0])&&Number.isFinite(f.geometry.coordinates[1])) };\n      map.getSource('waze-jams')?.setData(wazeJamData);\n      map.getSource('waze-alerts')?.setData(wazeAlertData);\n    },\n    setDest(p) { destM.setLngLat([p.lng, p.lat]).addTo(map); },\n    clearDest() { destM.remove(); },\n    popup(p, el) { popup?.remove(); popup = new maplibregl.Popup({ closeButton: false }).setLngLat([p.lng, p.lat]).setDOMContent(el).addTo(map); },\n    closePopup() { popup?.remove(); popup = null; },\n    on(ev, fn) {\n      if (ev === 'longpress') handlers.longpress = fn;\n      else if (ev === 'userMove') ['dragstart', 'rotatestart', 'pitchstart'].forEach(t => map.on(t, e => { if (e.originalEvent) fn(); }));\n      else if (ev === 'click') map.on('click', fn);\n      else if (ev === 'moveend') map.on('moveend', fn);\n    },\n  };\n}\n\nfunction classicMap() {\n  const map = L.map('map', { zoomControl: false, zoomSnap: 0.5, tap: false }).setView([saved.lat, saved.lng], saved.z);\n  // Keyless raster tiles: OpenStreetMap made dark with a CSS filter, or Esri's dark canvas.\n  const STYLES = {\n    osm: { name: 'OpenStreetMap', layers: [L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {\n      maxZoom: 20, maxNativeZoom: 19, className: 'dark-tiles', attribution: '© OpenStreetMap contributors' })] },\n    esri: { name: 'Esri tmavá', layers: [\n      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/{z}/{y}/{x}', {\n        maxZoom: 20, maxNativeZoom: 16, attribution: 'Tiles © Esri — Esri, HERE, Garmin, © OpenStreetMap contributors' }),\n      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Reference/MapServer/tile/{z}/{y}/{x}', {\n        maxZoom: 20, maxNativeZoom: 16 })] },\n  };\n  let styleKey = STYLES[store.get('style')] ? store.get('style') : 'osm';\n  STYLES[styleKey].layers.forEach(l => l.addTo(map));\n  map.attributionControl.setPrefix(false);\n\n  const carM = L.marker([0, 0], { interactive: false, zIndexOffset: 1000,\n    icon: L.divIcon({ className: '', iconSize: [52, 52], iconAnchor: [26, 26], html: '<div class=\"car\">' + CAR_SVG + '</div>' }) });\n  const destM = L.marker([0, 0], { interactive: false,\n    icon: L.divIcon({ className: '', iconSize: [40, 40], iconAnchor: [20, 38], html: DEST_SVG }) });\n  const acc = L.circle([0, 0], { radius: 0, stroke: false, fillColor: '#3e8bff', fillOpacity: 0.12, interactive: false });\n  const casing = L.polyline([], { color: '#0b2a57', weight: 14, opacity: 0.9, interactive: false });\n  const line = L.polyline([], { color: '#3e8bff', weight: 8, opacity: 1, interactive: false });\n  let popup = null;\n  const chargerLayer = L.layerGroup().addTo(map);\n  map.createPane('wazeTraffic');\n  map.getPane('wazeTraffic').style.zIndex = 450;\n  const wazeTrafficLayer = L.layerGroup().addTo(map);\n  const wazeAlertLayer = L.layerGroup().addTo(map);\n\n  return {\n    kind: 'classic', canRotate: false,\n    styleName: () => STYLES[styleKey].name,\n    nextStyle() {\n      STYLES[styleKey].layers.forEach(l => l.remove());\n      styleKey = styleKey === 'osm' ? 'esri' : 'osm'; store.set('style', styleKey);\n      STYLES[styleKey].layers.forEach(l => l.addTo(map));\n    },\n    center() { const c = map.getCenter(); return { lat: c.lat, lng: c.lng }; },\n    zoom: () => map.getZoom(),\n    bearing: () => 0,\n    setZoom(z) { map.setZoom(z, { animate: false }); },\n    jump(p, { zoom } = {}) { map.setView([p.lat, p.lng], zoom ?? map.getZoom(), { animate: false }); },\n    jumpAhead(p, course, frac) {\n      const z = map.getZoom(), size = map.getSize(), a = rad(course);\n      const pt = map.project([p.lat, p.lng], z).add(L.point(Math.sin(a) * size.x * frac, -Math.cos(a) * size.y * frac));\n      map.setView(map.unproject(pt, z), z, { animate: false });\n    },\n    fit(points, pad) {\n      map.fitBounds(L.latLngBounds(points.map(p => [p.lat, p.lng])),\n        { paddingTopLeft: [pad.left, pad.top], paddingBottomRight: [pad.right, pad.bottom], maxZoom: 17 });\n    },\n    setCar(p, heading) {\n      if (!map.hasLayer(carM)) carM.addTo(map);\n      carM.setLatLng([p.lat, p.lng]);\n      const el = carM.getElement();\n      if (el) el.firstChild.style.transform = `rotate(${heading}deg)`;\n    },\n    setAcc(p, r) { if (!map.hasLayer(acc)) acc.addTo(map); acc.setLatLng([p.lat, p.lng]).setRadius(r); },\n    setRoute(points) { const ll = points.map(p => [p.lat, p.lng]); casing.setLatLngs(ll).addTo(map); line.setLatLngs(ll).addTo(map); },\n    clearRoute() { casing.remove(); line.remove(); },\n    setChargers(list, onTap) {\n      chargerLayer.clearLayers();\n      list.forEach(c => {\n        const kw = Math.round(parseFloat(c.p) || 0);\n        const icon = L.divIcon({\n          className: 'charger-power-icon',\n          html: '<div class=\"charger-power-bubble\">' + (kw || '?') + '</div>',\n          iconSize: [34,34],\n          iconAnchor: [17,17]\n        });\n        L.marker([c.lat, c.lng], { icon }).on('click', () => onTap(c)).addTo(chargerLayer);\n      });\n    },\n    bounds() {\n      const b = map.getBounds();\n      return { top:b.getNorth(), bottom:b.getSouth(), left:b.getWest(), right:b.getEast() };\n    },\n    setWaze(alerts, jams, onTap) {\n      wazeTrafficLayer.clearLayers();\n      wazeAlertLayer.clearLayers();\n      const jamColor = l => l >= 4 ? '#b91c1c' : l === 3 ? '#ef4444' : l === 2 ? '#f59e0b' : '#facc15';\n      (jams||[]).forEach(j => {\n        const pts=(j.line||[]).map(p => [Number(p.lat),Number(p.lng)]).filter(p => Number.isFinite(p[0])&&Number.isFinite(p[1]));\n        if(pts.length>1) L.polyline(pts,{pane:'wazeTraffic',color:jamColor(Number(j.level)||0),weight:9,opacity:.95,interactive:false}).addTo(wazeTrafficLayer);\n      });\n      (alerts||[]).forEach(a => {\n        const lat=Number(a.lat),lng=Number(a.lng); if(!Number.isFinite(lat)||!Number.isFinite(lng))return;\n        const v=wazeAlertVisual(a.type);\n        const icon=L.divIcon({className:'waze-alert-icon',html:'<div class=\"waze-alert-bubble '+v.kind+'\">'+v.label+'</div>',iconSize:[34,34],iconAnchor:[17,17]});\n        L.marker([lat,lng],{icon,zIndexOffset:700}).on('click',()=>onTap(a)).addTo(wazeAlertLayer);\n      });\n    },\n    setDest(p) { destM.setLatLng([p.lat, p.lng]).addTo(map); },\n    clearDest() { destM.remove(); },\n    popup(p, el) { popup = L.popup({ closeButton: false }).setLatLng([p.lat, p.lng]).setContent(el).openOn(map); },\n    closePopup() { if (popup) map.closePopup(popup); popup = null; },\n    on(ev, fn) {\n      if (ev === 'longpress') map.on('contextmenu', e => fn({ lat: e.latlng.lat, lng: e.latlng.lng }));\n      else if (ev === 'userMove') map.on('dragstart', fn);\n      else map.on(ev, fn);\n    },\n  };\n}\n\nconst M = engine === 'vector' ? vectorMap() : classicMap();\nM.on('moveend', () => { const c = M.center(); store.set('view', { lat: c.lat, lng: c.lng, z: M.zoom() }); });\n\nfunction wazeAlertVisual(type) {\n  const t=String(type||'').toUpperCase();\n  if(t.includes('POLICE')) return {kind:'police',label:'🚓',name:'Policajná hliadka'};\n  if(t.includes('ACCIDENT')) return {kind:'accident',label:'💥',name:'Nehoda'};\n  if(t.includes('ROAD_CLOSED')||t.includes('CLOSURE')) return {kind:'closure',label:'⛔',name:'Uzávierka'};\n  if(t.includes('CAMERA')) return {kind:'camera',label:'📷',name:'Pevný radar'};\n  if(t.includes('JAM')) return {kind:'jam',label:'!',name:'Kolóna'};\n  if(t.includes('CONSTRUCTION')) return {kind:'hazard',label:'🚧',name:'Práce na ceste'};\n  return {kind:'hazard',label:'⚠',name:'Nebezpečenstvo'};\n}\nfunction showWazeAlert(a) {\n  const v=wazeAlertVisual(a.type);\n  const el=document.createElement('div');\n  el.style.cssText='min-width:220px;font-size:16px';\n  const where=[a.street,a.city].filter(Boolean).join(', ');\n  const age=a.pubMillis ? Math.max(0,Math.round((Date.now()-Number(a.pubMillis))/60000)) : null;\n  el.innerHTML='<b>'+esc(v.name)+'</b>'+(where?'<div style=\"color:var(--quiet);margin-top:4px\">'+esc(where)+'</div>':'')+\n    (age!=null?'<div style=\"color:var(--quiet);font-size:13px;margin-top:4px\">Waze · pred '+age+' min</div>':'');\n  M.popup({lat:Number(a.lat),lng:Number(a.lng)},el);\n}\nlet wazeLoadSeq=0,wazeRefreshTimer=null;\nlet wazeAlerts=[],wazeEventJams=[],wazeRouteJams=[];\nlet wazeTrafficAt=0,wazeTrafficDestKey='',wazePassedAlong=0,wazeLastPaintAlong=-Infinity;\n\nfunction projectTrafficPointToRoute(p,r){\n  if(!r?.pts?.length||r.pts.length<2||!Number.isFinite(Number(p?.lat))||!Number.isFinite(Number(p?.lng)))return null;\n  const q={lat:Number(p.lat),lng:Number(p.lng)};\n  let best=null;\n  for(let i=0;i<r.pts.length-1;i++){\n    const s=projSeg(q,r.pts[i],r.pts[i+1]);\n    if(!best||s.d<best.d){\n      const a=r.pts[i],b=r.pts[i+1];\n      best={\n        d:s.d,\n        along:r.cum[i]+s.t*(r.cum[i+1]-r.cum[i]),\n        point:{lat:a.lat+(b.lat-a.lat)*s.t,lng:a.lng+(b.lng-a.lng)*s.t}\n      };\n    }\n  }\n  return best;\n}\n\nfunction routeSliceBetween(r,fromAlong,toAlong){\n  const a=Math.max(0,Math.min(r.total,fromAlong));\n  const b=Math.max(0,Math.min(r.total,toAlong));\n  if(b-a<4)return [];\n  const start=pointAt(r,a),end=pointAt(r,b),out=[{lat:start.lat,lng:start.lng}];\n  for(let i=start.idx+1;i<=end.idx&&i<r.pts.length;i++){\n    const along=r.cum[i];\n    if(along>a+1&&along<b-1)out.push(r.pts[i]);\n  }\n  const last=out[out.length-1];\n  if(!last||dist(last,end)>1)out.push({lat:end.lat,lng:end.lng});\n  return out;\n}\n\nfunction trafficJamOnActiveRoute(j,r,passedAlong){\n  if(!r||!Array.isArray(j?.line)||j.line.length<2)return null;\n\n  const a=j.line[0],b=j.line[j.line.length-1];\n  const mid={\n    lat:(Number(a.lat)+Number(b.lat))/2,\n    lng:(Number(a.lng)+Number(b.lng))/2\n  };\n  const center=projectTrafficPointToRoute(mid,r);\n  if(!center||center.d>160)return null;\n\n  // Waze geometry can run beside the OSRM geometry. Keep Waze's traffic length,\n  // but draw that length directly on our active route around the projected centre.\n  const rawLength=Number(j.length)||dist(\n    {lat:Number(a.lat),lng:Number(a.lng)},\n    {lat:Number(b.lat),lng:Number(b.lng)}\n  );\n  const span=Math.max(20,Math.min(1200,rawLength||20));\n  let from=Math.max(0,center.along-span/2);\n  let to=Math.min(r.total,center.along+span/2);\n\n  if(to<=passedAlong+4)return null;\n  from=Math.max(from,passedAlong);\n\n  const line=routeSliceBetween(r,from,to);\n  if(line.length<2)return null;\n  return {...j,line,_routeFrom:from,_routeTo:to,_snapDistance:center.d};\n}\n\nfunction paintWazeOverlay(){\n  if(!M.setWaze)return;\n  const seen=new Set(),jams=[];\n  if(route){\n    for(const j of [...wazeEventJams,...wazeRouteJams]){\n      const snapped=trafficJamOnActiveRoute(j,route,wazePassedAlong);\n      if(!snapped)continue;\n      const p=snapped.line[0]||{};\n      const key=String(snapped.id||'')+'|'+Number(p.lat).toFixed(5)+'|'+Number(p.lng).toFixed(5);\n      if(seen.has(key))continue;\n      seen.add(key);jams.push(snapped);\n    }\n  }\n  M.setWaze(wazeAlerts,jams,showWazeAlert);\n}\n\nasync function refreshWazeRouteTraffic(force=false){\n  if(!route||!dest){wazeRouteJams=[];wazeTrafficAt=0;wazeTrafficDestKey='';paintWazeOverlay();return}\n  const from=pos||M.center();\n  if(!from||![from.lat,from.lng,dest.lat,dest.lng].every(Number.isFinite))return;\n  const destKey=Number(dest.lat).toFixed(4)+','+Number(dest.lng).toFixed(4);\n  if(!force&&destKey===wazeTrafficDestKey&&Date.now()-wazeTrafficAt<45000)return;\n  try{\n    const u='/api/traffic?fromLat='+encodeURIComponent(from.lat)+'&fromLng='+encodeURIComponent(from.lng)+\n      '&toLat='+encodeURIComponent(dest.lat)+'&toLng='+encodeURIComponent(dest.lng);\n    const r=await fetch(u,{cache:'no-store'});\n    if(!r.ok)throw new Error('traffic '+r.status);\n    const d=await r.json();\n    wazeRouteJams=Array.isArray(d.jams)?d.jams:[];\n    wazeTrafficAt=Date.now();wazeTrafficDestKey=destKey;\n    paintWazeOverlay();\n  }catch{}\n}\n\nasync function refreshWazeOverlay() {\n  if(!M.bounds||!M.setWaze)return;\n  const b=M.bounds(),c=M.center();\n  let top=b.top,bottom=b.bottom,left=b.left,right=b.right;\n  if(top-bottom>1.2){top=c.lat+.6;bottom=c.lat-.6}\n  if(right-left>1.8){right=c.lng+.9;left=c.lng-.9}\n  const seq=++wazeLoadSeq;\n  const traffic=refreshWazeRouteTraffic(false);\n  try{\n    const u='/api/events?top='+encodeURIComponent(top)+'&bottom='+encodeURIComponent(bottom)+'&left='+encodeURIComponent(left)+'&right='+encodeURIComponent(right);\n    const r=await fetch(u,{cache:'no-store'});\n    if(!r.ok)throw new Error('events '+r.status);\n    const d=await r.json();\n    if(seq!==wazeLoadSeq)return;\n    wazeAlerts=Array.isArray(d.alerts)?d.alerts:[];\n    wazeEventJams=Array.isArray(d.jams)?d.jams:[];\n    paintWazeOverlay();\n  }catch{}\n  await traffic;\n}\nfunction scheduleWazeRefresh(){\n  clearTimeout(wazeRefreshTimer);\n  wazeRefreshTimer=setTimeout(refreshWazeOverlay,650);\n}\nM.on('moveend', scheduleWazeRefresh);\nsetInterval(refreshWazeOverlay,60000);\nsetTimeout(refreshWazeOverlay,1400);\n\n// ---------------------------------------------------------------- state\nlet pos = null;              // latest fix {lat,lng,speed,course,acc,ts,src}\nlet shown = null;            // position currently drawn (animated towards pos)\nlet follow = true;\nlet route = null;            // see buildRoute()\nlet dest = null;             // {lat,lng,name}\nlet source = 'none';         // 'phone' | 'browser' | 'none'\nlet mode = 'map';            // 'map' | 'mirror'\nlet sim = null;\nlet voiceOn = store.get('voice', true);\nlet voiceVolume = Math.max(.2, Math.min(1, Number(store.get('voiceVolume', .7)) || .7));\nlet arrived = false;\n\n// ---------------------------------------------------------------- position\nlet heading = 0, shownHeading = 0, anim = null;\n// Heading-up: the map turns so the road ahead is always up (vector map only).\nlet headingUp = store.get('headingUp', true);\n\nfunction onFix(p) {\n  if (sim && p.src !== 'sim') return;\n  if (!(p.course >= 0)) p.course = pos && dist(pos, p) > 4 ? bearing(pos, p) : (pos ? pos.course : 0);\n  const first = !pos;\n  pos = p;\n  M.setAcc(p, Math.min(p.acc || 0, 200));\n  rotateCar(p.course);\n  if (first) { shown = p; shownHeading = heading; M.jump(p, { zoom: 16 }); }\n  animateTo(p);\n\n  const kmh = p.speed > 0 ? Math.round(p.speed * 3.6) : 0;\n  show($('speed'), true);\n  $('speed').querySelector('b').textContent = kmh;\n\n  if (route) navUpdate();\n  else if (dest && first) routeTo(dest, { resume: true });\n}\n\nfunction rotateCar(course) {\n  // Take the short way round: 350° → 10° turns 20°, not 340°.\n  heading += ((course - heading + 540) % 360) - 180;\n}\n\n/** Glide the car (and heading) to the new fix over ~1 s so the map moves smoothly. */\nfunction animateTo(p) {\n  const from = shown || p, fromHeading = shownHeading, t0 = performance.now(), dur = 900;\n  cancelAnimationFrame(anim);\n  const step = now => {\n    const k = Math.min(1, (now - t0) / dur);\n    shown = { lat: from.lat + (p.lat - from.lat) * k, lng: from.lng + (p.lng - from.lng) * k };\n    shownHeading = fromHeading + (heading - fromHeading) * k;\n    M.setCar(shown, shownHeading);\n    if (follow) followCar();\n    if (k < 1) anim = requestAnimationFrame(step);\n  };\n  anim = requestAnimationFrame(step);\n}\n\n/**\n * Keep the car in view. Heading-up (vector map): the map turns with the car, tilts, and the\n * car sits low on screen so the road ahead fills it. North-up: the view is pushed ahead of the\n * car in the direction it's driving.\n */\nfunction followCar() {\n  if (!shown) return;\n  if (M.canRotate && headingUp && route) return M.jump(shown, { bearing: shownHeading, pitch: 45, ahead: 0.22 });\n  if (M.canRotate && headingUp && pos && pos.speed > 2) return M.jump(shown, { bearing: shownHeading, pitch: 0, ahead: 0.12 });\n  if (!route) return M.jump(shown);\n  M.jumpAhead(shown, shownHeading, 0.22);\n}\n\nfunction renderNorth() {\n  show($('northBtn'), M.canRotate);\n  $('northBtn').innerHTML = `<svg viewBox=\"0 0 24 24\" style=\"transform:rotate(${headingUp ? 0 : 0}deg)\" fill=\"currentColor\"><path d=\"M12 2l7 19-7-4-7 4z\"/></svg>${headingUp ? 'SMER' : 'S'}`;\n}\n$('northBtn').onclick = () => {\n  headingUp = !headingUp; store.set('headingUp', headingUp); renderNorth();\n  if (!headingUp && M.canRotate && shown) M.jump(shown, { bearing: 0, pitch: 0 });\n  setFollow(true);\n};\nrenderNorth();\n\nfunction setFollow(on) {\n  follow = on;\n  show($('recenter'), !on && !!pos);\n  if (on && pos) {\n    if (route && M.zoom() < 16) M.setZoom(17);\n    followCar();\n  }\n}\nM.on('userMove', () => setFollow(false));\n$('recenter').onclick = () => setFollow(true);\n\n// ---------------------------------------------------------------- location sources\nfunction useBrowserLocation() {\n  if (!('geolocation' in navigator)) { source = 'none'; setStatus('Nie je dostupná poloha — otvorte stránku z aplikácie HotspotNav na iPhone', 'bad'); return; }\n  source = 'browser';\n  navigator.geolocation.watchPosition(g => {\n    const c = g.coords;\n    onFix({ lat: c.latitude, lng: c.longitude, speed: c.speed ?? -1, course: c.heading ?? -1, acc: c.accuracy, ts: g.timestamp, src: 'browser' });\n  }, e => setStatus('Poloha z prehliadača nie je dostupná: ' + e.message, 'bad'),\n  { enableHighAccuracy: true, maximumAge: 1000, timeout: 20000 });\n}\n\n/** The Tesla browser shares the car's own GPS with web pages. */\nfunction detectSource() {\n  useBrowserLocation();\n}\n\n// ---------------------------------------------------------------- search\nlet searchSeq = 0, searchTimer;\nconst q = $('q'), results = $('results');\n\nfunction renderResults(items, note) {\n  results.innerHTML = note ? `<div class=\"res note\">${esc(note)}</div>` : '';\n  for (const it of items) {\n    const div = document.createElement('div');\n    div.className = 'res';\n    const away = pos ? ' · ' + fmtDist(dist(pos, it)) : '';\n    div.innerHTML = `<b>${esc(it.name)}</b><span>${esc((it.detail || '') + away)}</span>`;\n    div.onclick = () => choose(it);\n    results.appendChild(div);\n  }\n}\n\nfunction showRecents() {\n  const recents = store.get('recent', []);\n  renderResults(recents, recents.length ? '' : '');\n  if (recents.length) results.insertAdjacentHTML('afterbegin', '<div class=\"res note\">Recent</div>');\n}\n\nasync function search() {\n  const text = q.value.trim();\n  show($('clearQ'), !!text);\n  if (text.length < 3) return showRecents();\n  const m = text.match(/^\\s*(-?\\d{1,2}(?:\\.\\d+)?)\\s*[,\\s]\\s*(-?\\d{1,3}(?:\\.\\d+)?)\\s*$/);\n  if (m) return renderResults([{ name: 'Súradnice', detail: `${m[1]}, ${m[2]}`, lat: +m[1], lng: +m[2] }]);\n\n  const c = pos || M.center();\n  const seq = ++searchSeq;\n  // The offline index answers instantly; Photon's online results are added below it.\n  let local = [];\n  try { local = await searchLocal(text, c); } catch {}\n  if (seq !== searchSeq) return;\n  if (local.length) renderResults(local);\n  try {\n    const online = await searchPhoton(text, c);\n    if (seq !== searchSeq) return;\n    const merged = local.concat(online.filter(o => !local.some(l => dist(l, o) < 60))).slice(0, 10);\n    renderResults(merged, merged.length ? '' : 'Nič sa nenašlo');\n  } catch {\n    if (local.length) return;\n    try {\n      const items = await searchNominatim(text, c);\n      if (seq === searchSeq) renderResults(items, items.length ? '' : 'Nič sa nenašlo');\n    } catch {\n      if (seq === searchSeq) renderResults([], 'Vyhľadávanie zlyhalo — nie je internet?');\n    }\n  }\n}\n\n// ---------------------------------------------------------------- offline search (Armenia)\n// data/am-search.json is built from OpenStreetMap by tools/build_search_index.py. Every name\n// and every query goes through fold(), which transliterates Armenian and Cyrillic to Latin and\n// merges spelling variants, so \"kaskad\", \"Каскад\", \"Կասկադ\" and \"cascade\" all meet.\nconst ARMENIA = { s: 38.7, n: 41.4, w: 43.3, e: 46.8 };\nconst inArmenia = p => p.lat > ARMENIA.s && p.lat < ARMENIA.n && p.lng > ARMENIA.w && p.lng < ARMENIA.e;\nconst HY = { 'ա':'a','բ':'b','գ':'g','դ':'d','ե':'e','զ':'z','է':'e','ը':'e','թ':'t','ժ':'zh','ի':'i','լ':'l','խ':'kh','ծ':'ts',\n  'կ':'k','հ':'h','ձ':'dz','ղ':'gh','ճ':'ch','մ':'m','յ':'y','ն':'n','շ':'sh','ո':'o','չ':'ch','պ':'p','ջ':'j','ռ':'r','ս':'s',\n  'վ':'v','տ':'t','ր':'r','ց':'ts','ւ':'v','փ':'p','ք':'k','և':'ev','օ':'o','ֆ':'f' };\nconst RU = { 'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'e','ж':'zh','з':'z','и':'i','й':'i','к':'k','л':'l','м':'m',\n  'н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'kh','ц':'ts','ч':'ch','ш':'sh','щ':'sh','ъ':'','ы':'y',\n  'ь':'','э':'e','ю':'yu','я':'ya' };\n\n/** Folds a name or query to a spelling-insensitive Latin \"sound key\". */\nfunction fold(text) {\n  // Drop accents and invisible marks (OSM names sometimes carry a left-to-right mark mid-word).\n  let t = text.toLowerCase().normalize('NFKD').replace(/[\\u0300-\\u036f\\u200b-\\u200f\\u00ad\\u2060]/g, '').replace(/ու/g, 'u');\n  t = t.replace(/[\\u0561-\\u0587]/g, ch => HY[ch] ?? ch).replace(/[\\u0430-\\u044f\\u0451]/g, ch => RU[ch] ?? ch);\n  t = t.replace(/x/g, 'kh').replace(/tch/g, 'ch').replace(/ch/g, 'C').replace(/sh/g, 'S').replace(/zh/g, 'Z')\n       .replace(/kh/g, 'H').replace(/gh/g, 'H').replace(/ts|tz/g, 'T').replace(/dz/g, 'D').replace(/ph/g, 'p')\n       .replace(/th/g, 't').replace(/ck/g, 'k').replace(/c/g, 'k').replace(/q/g, 'k').replace(/w/g, 'v')\n       .replace(/y/g, 'i').replace(/h/g, 'H').replace(/ou/g, 'u');\n  return t.split(/[^a-zA-Z0-9]+/).filter(Boolean)\n          // Yerevan/Erevan; doubled letters; English silent final e (Cascade → kaskad).\n          .map(w => w.replace(/^ie/, 'e').replace(/(.)\\1+/g, '$1').replace(/^(.{4,}[^aeiou])e$/, '$1'));\n}\n// Words that say what kind of thing it is, not which one (\"street\", \"улица\", \"փողոց\"...).\nconst STOP = new Set(['street', 'st', 'str', 'avenue', 'ave', 'road', 'rd', 'lane', 'square', 'district', 'ulitsa', 'ul',\n  'prospekt', 'pr', 'ploshad', 'poghots', 'poghota', 'poxoc', 'poghoc', 'taghamas', 'nrbanTsk', 'hraparak', 'mairughi',\n  'улица', 'проспект', 'փողոց', 'պողոտա', 'թաղամաս', 'նրբանցք', 'հրապարակ', 'մայրուղի'].flatMap(fold));\nconst words = text => fold(text).filter(w => !STOP.has(w));\n\nconst CHARGER_WORDS = ['charger', 'charging', 'charge', 'chargers', 'ev', 'зарядка', 'зарядная', 'зарядные', 'заряд',\n  'լիցքավորում', 'լիցքավորման', 'lickavorum'].flatMap(fold);\nconst isLatin = t => /^[\\x00-\\x7F«»“”‘’–—]+$/.test(t);\nlet searchIndex = null, addressIndex = null;\n\n/** Loads the index once, the first time it's useful (the car is in or near Armenia). */\nfunction loadSearchIndex() {\n  if (searchIndex) return searchIndex;\n  searchIndex = fetch('data/am-search.json').then(r => r.json()).then(d => {\n    const towns = d.towns.map(([name, alts]) => alts.find(isLatin) || name);\n    const entries = d.e.map(([kind, name, alts, lat, lng, town, extra]) => {\n      const all = [name, ...alts];\n      return { kind, name, alts, lat: lat / 1e5, lng: lng / 1e5, town: town >= 0 ? towns[town] : '', extra,\n               display: isLatin(name) ? name : (alts.find(isLatin) || name), keys: all.map(words) };\n    });\n    return { entries };\n  });\n  return searchIndex;\n}\nfunction loadAddresses() {\n  if (addressIndex) return addressIndex;\n  addressIndex = fetch('data/am-addresses.json').then(r => r.json()).then(d =>\n    Object.entries(d.streets).map(([street, list]) => ({ street, keys: words(street), list })));\n  return addressIndex;\n}\nq.addEventListener('focus', () => { const c = pos || M.center(); if (inArmenia(c)) loadSearchIndex(); });\n\n/** How well query words `qw` match a name's words `kw` (0 = no match). */\nfunction matchScore(qw, kw) {\n  if (!qw.length || !kw.length) return 0;\n  let score = 0;\n  for (const w of qw) {\n    let best = 0;\n    for (let i = 0; i < kw.length; i++) {\n      const k = kw[i];\n      const s = k === w ? 10 : k.startsWith(w) ? 7 : (w.length >= 4 && k.includes(w)) ? 3 : 0;\n      if (s > best) best = s + (i === 0 ? 1 : 0);\n    }\n    if (!best) return 0;\n    score += best;\n  }\n  if (qw.length === kw.length && qw.every((w, i) => w === kw[i])) score += 8;   // the whole name\n  return score;\n}\n\nconst KIND_WEIGHT = [30, 22, 22, 10, 14];            // town, village, district, place, street\nconst KIND_LABEL = ['Town', 'Village', 'District', '', 'Street'];\n// Places people drive to by name get a head start over the shop that borrowed it.\nconst LANDMARK = new Set(['attraction', 'museum', 'mall', 'marketplace', 'stadium', 'theatre', 'university', 'hospital',\n  'station', 'aerodrome', 'monument', 'memorial', 'park', 'zoo', 'viewpoint', 'monastery', 'church', 'fort', 'castle']);\n\n/** English name of the street an address is on (from the street entries) and its town. */\nfunction describeAddress(entries, streetName, p) {\n  let street = streetName, streetTown = '', best = Infinity, nearestTown = '', bestTown = Infinity;\n  for (const e of entries) {\n    const d = dist(p, e);\n    if (e.kind === 4 && e.name === streetName && d < best) { best = d; street = e.display; streetTown = e.town; }\n    else if (e.kind <= 1 && d < bestTown) { bestTown = d; nearestTown = e.display; }\n  }\n  return { street, town: best < 5000 ? streetTown : nearestTown };\n}\n\nasync function searchLocal(text, c) {\n  if (!inArmenia(c)) return [];\n  const { entries } = await loadSearchIndex();\n  const house = text.match(/(?:^|\\s)(\\d+[a-zա-ֆа-я]?(?:\\/\\d+)?)(?=\\s|$)/i);\n  const qw = words(text.replace(house ? house[1] : '', ' '));\n  const found = [];\n  if (house && qw.length) {\n    // \"Abovyan 10\": the street, then the house on it nearest to where we are.\n    for (const s of await loadAddresses()) {\n      const m = matchScore(qw, s.keys);\n      if (!m) continue;\n      for (const [hn, lat, lng] of s.list) {\n        if (hn.toLowerCase() !== house[1].toLowerCase()) continue;\n        const p = { lat: lat / 1e5, lng: lng / 1e5 };\n        const { street, town } = describeAddress(entries, s.street, p);\n        found.push({ score: 40 + m - 12 * Math.log10(1 + dist(c, p) / 1000), name: `${street} ${hn}`, detail: ['Address', town].filter(Boolean).join(' · '), ...p });\n      }\n    }\n  }\n  if (qw.length) {\n    for (const e of entries) {\n      let m = 0;\n      for (const k of e.keys) m = Math.max(m, matchScore(qw, k));\n      if (!m) continue;\n      const km = dist(c, e) / 1000;\n      const score = m + KIND_WEIGHT[e.kind] - 12 * Math.log10(1 + km) + (e.kind <= 2 && e.extra ? Math.log10(1 + e.extra) : 0)\n                  + (e.kind === 3 && LANDMARK.has(e.extra) ? (e.extra === 'attraction' || e.extra === 'museum' ? 8 : 6) : 0);\n      const label = e.kind === 3 ? (e.extra === 'yes' ? '' : (e.extra || '').replace(/_/g, ' ')) : KIND_LABEL[e.kind];\n      const detail = [e.display !== e.name ? e.name : '', label, e.town].filter(Boolean).join(' · ');\n      found.push({ score, name: e.display, detail, lat: e.lat, lng: e.lng });\n    }\n  }\n  // Nabíjačky EV: by name or operator, or all nearby for \"charger\", \"зарядка\", \"լիցքավորում\"…\n  const wantsChargers = CHARGER_WORDS.some(k => qw.some(w => w.length >= 3 && k.startsWith(w)));\n  if (qw.length) {\n    for (const ch of await loadChargers()) {\n      const m = wantsChargers ? 12 : Math.max(matchScore(qw, words(ch.n)), ch.o ? matchScore(qw, words(ch.o)) : 0);\n      if (!m) continue;\n      const detail = ['EV charger', ch.o, ch.s.join(', ') || 'connectors not listed'].filter(Boolean).join(' · ');\n      found.push({ score: m + 14 - 12 * Math.log10(1 + dist(c, ch) / 1000), name: '⚡ ' + ch.n, detail, lat: ch.lat, lng: ch.lng });\n    }\n  }\n  found.sort((a, b) => b.score - a.score);\n  // One result per place: a street's segments or a shop's duplicates within 150 m collapse.\n  const out = [];\n  for (const f of found) {\n    if (out.some(o => o.name === f.name && dist(o, f) < 150)) continue;\n    out.push(f);\n    if (out.length === 8) break;\n  }\n  return out;\n}\n\n/**\n * Photon (OSM data, made for typing as you search). Its \"near me\" bias alone still lets an\n * exact name match in another country outrank the place down the road, so search within\n * ~100 km first and only fill up from everywhere when that finds too little.\n */\nasync function searchPhoton(text, c) {\n  const base = `https://photon.komoot.io/api/?q=${encodeURIComponent(text)}&lat=${c.lat.toFixed(4)}&lon=${c.lng.toFixed(4)}&limit=8`;\n  const bbox = [c.lng - 1.2, c.lat - 0.9, c.lng + 1.2, c.lat + 0.9].map(v => v.toFixed(4)).join(',');\n  const near = (await (await fetchT(`${base}&bbox=${bbox}`, 7000)).json()).features.map(toPhotonItem);\n  if (near.length >= 3) return near;\n  const wide = (await (await fetchT(base, 7000)).json()).features.map(toPhotonItem);\n  return near.concat(wide.filter(w => !near.some(n => dist(n, w) < 30))).slice(0, 8);\n}\n\nfunction toPhotonItem(f) {\n    const p = f.properties, [lng, lat] = f.geometry.coordinates;\n    const street = [p.street, p.housenumber].filter(Boolean).join(' ');\n    const name = p.name || street || p.city || 'Place';\n    const detail = [p.name ? street : '', p.district, p.city, p.country].filter(Boolean).join(', ');\n    return { name, detail, lat, lng };\n}\n\n/** Backup: Nominatim, nearby matches first (~60 km box), then from everywhere. */\nasync function searchNominatim(text, c) {\n  const vb = [c.lng - 0.7, c.lat + 0.5, c.lng + 0.7, c.lat - 0.5].map(v => v.toFixed(4)).join(',');\n  const base = `https://nominatim.openstreetmap.org/search?format=jsonv2&limit=7&q=${encodeURIComponent(text)}`;\n  const toItem = x => {\n    const parts = x.display_name.split(', ');\n    return { name: x.name || parts[0], detail: parts.slice(1).join(', '), lat: +x.lat, lng: +x.lon, id: x.place_id };\n  };\n  let items = (await (await fetchT(`${base}&viewbox=${vb}&bounded=1`, 8000)).json()).map(toItem);\n  items.sort((a, b) => dist(c, a) - dist(c, b));\n  if (items.length < 3) {\n    const wide = (await (await fetchT(`${base}&viewbox=${vb}`, 8000)).json()).map(toItem);\n    items = items.concat(wide.filter(w => !items.some(i => i.id === w.id))).slice(0, 7);\n  }\n  return items;\n}\n\nq.addEventListener('input', () => { clearTimeout(searchTimer); searchTimer = setTimeout(search, 600); });\nq.addEventListener('keydown', e => { if (e.key === 'Enter') { clearTimeout(searchTimer); search(); } });\nq.addEventListener('focus', () => { if (!q.value.trim()) showRecents(); });\n$('clearQ').onclick = () => { q.value = ''; show($('clearQ'), false); results.innerHTML = ''; q.focus(); };\nM.on('click', () => { results.innerHTML = ''; q.blur(); $('menu').classList.add('hidden'); });\n\nlet quickAssign = null;\nfunction quickPlaces() { return store.get('quickPlaces', { home: null, work: null }) || { home: null, work: null }; }\nfunction renderQuickPlaces() {\n  const qp = quickPlaces();\n  $('homeBtn').classList.toggle('unset', !qp.home);\n  $('workBtn').classList.toggle('unset', !qp.work);\n}\nfunction beginQuickAssign(kind) {\n  quickAssign = kind;\n  q.value = '';\n  results.innerHTML = '';\n  show($('clearQ'), false);\n  q.placeholder = kind === 'home' ? 'Vyhľadajte adresu domova…' : 'Vyhľadajte adresu práce…';\n  q.focus();\n  toast(kind === 'home' ? 'Vyberte adresu domova' : 'Vyberte adresu práce', 3000);\n}\nfunction useQuick(kind) {\n  const p = quickPlaces()[kind];\n  if (!p) return beginQuickAssign(kind);\n  choose(p);\n}\nfunction bindQuickButton(id, kind) {\n  const el = $(id);\n  let timer = null, long = false;\n  el.addEventListener('pointerdown', () => {\n    long = false;\n    timer = setTimeout(() => { long = true; beginQuickAssign(kind); }, 700);\n  });\n  ['pointerup','pointercancel','pointerleave'].forEach(ev => el.addEventListener(ev, () => {\n    clearTimeout(timer);\n    if (ev === 'pointerup' && !long) useQuick(kind);\n  }));\n}\nbindQuickButton('homeBtn', 'home');\nbindQuickButton('workBtn', 'work');\nrenderQuickPlaces();\n\nfunction choose(it) {\n  if (quickAssign) {\n    const qp = quickPlaces();\n    qp[quickAssign] = { name: it.name, detail: it.detail || '', lat: it.lat, lng: it.lng };\n    store.set('quickPlaces', qp);\n    toast((quickAssign === 'home' ? 'Domov' : 'Práca') + ' uložené', 2500);\n    quickAssign = null;\n    q.placeholder = 'Kam chcete ísť?';\n    renderQuickPlaces();\n  }\n  const recents = store.get('recent', []).filter(r => r.name !== it.name || dist(r, it) > 50);\n  recents.unshift({ name: it.name, detail: it.detail, lat: it.lat, lng: it.lng });\n  store.set('recent', recents.slice(0, 8));\n  results.innerHTML = ''; q.value = ''; show($('clearQ'), false); q.blur();\n  routeTo({ lat: it.lat, lng: it.lng, name: it.name });\n}\n\n// Long-press anywhere on the map to drive there.\nM.on('longpress', ll => {\n  const btn = document.createElement('button');\n  btn.className = 'primary'; btn.textContent = 'Navigovať sem';\n  M.popup(ll, btn);\n  btn.onclick = () => { M.closePopup(); routeTo({ lat: ll.lat, lng: ll.lng, name: 'Označené miesto' }); };\n});\n\n// ---------------------------------------------------------------- routing\nlet routing = false;\n\nasync function routeTo(d, { reroute = false, resume = false } = {}) {\n  if (routing) return;\n  const from = pos || M.center();\n  let url = `https://router.project-osrm.org/route/v1/driving/${from.lng.toFixed(6)},${from.lat.toFixed(6)};` +\n            `${d.lng.toFixed(6)},${d.lat.toFixed(6)}?overview=false&steps=true&geometries=geojson`;\n  // Moving: start the route in the direction we're already going, not with a U-turn.\n  if (pos && pos.speed > 3 && pos.course >= 0) url += `&bearings=${Math.round(pos.course)},60;`;\n  routing = true;\n  if (!reroute) toast('Hľadám trasu…', 10000);\n  try {\n    const j = await (await fetchT(url, 12000)).json();\n    if (j.code !== 'Ok' || !j.routes || !j.routes.length) throw new Error(j.message || 'no route');\n    const fresh = !route || !reroute;\n    setRoute(buildRoute(j.routes[0]), d);\n    if (fresh) {\n      toast(`${fmtDuration(route.duration)} · ${fmtDist(route.total)}`);\n      if (!resume) say(`Spúšťam navigáciu do cieľa ${d.name || ''}.`);\n      overview(true);\n      if (params.has('sim') && !sim) setTimeout(() => { if (!sim) toggleSim(); }, 5500);\n    }\n  } catch (e) {\n    toast('Nepodarilo sa nájsť trasu' + (e.name === 'AbortError' ? ' — nie je internet?' : ': ' + e.message));\n  } finally {\n    routing = false;\n    if (route) route.lastReroute = Date.now();\n  }\n}\n\n/**\n * The route is rebuilt from the step geometries rather than the overview, so every step\n * knows exactly where on the polyline its maneuver is.\n */\nfunction buildRoute(rt) {\n  const pts = [], steps = [];\n  for (const leg of rt.legs) for (const st of leg.steps) {\n    const startIdx = pts.length ? pts.length - 1 : 0;\n    st.geometry.coordinates.forEach((c, i) => { if (!(pts.length && i === 0)) pts.push({ lat: c[1], lng: c[0] }); });\n    const m = st.maneuver;\n    steps.push({ startIdx, dur: st.duration, type: m.type, mod: m.modifier || '', exit: m.exit,\n                 bearingAfter: m.bearing_after, name: st.name || '', ref: st.ref || '' });\n  }\n  const cum = [0];\n  for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + dist(pts[i - 1], pts[i]));\n  const total = cum[cum.length - 1];\n  steps.forEach((s, i) => { s.start = cum[s.startIdx]; s.text = instruction(s); });\n  steps.forEach((s, i) => { s.end = i + 1 < steps.length ? steps[i + 1].start : total; });\n  const after = new Array(steps.length).fill(0);   // seconds of driving after step i\n  for (let i = steps.length - 2; i >= 0; i--) after[i] = after[i + 1] + steps[i + 1].dur;\n  return { pts, cum, total, steps, after, duration: rt.duration, hint: 0, off: 0, lastReroute: Date.now(), ann: {} };\n}\n\nfunction setRoute(r, d) {\n  route = r; dest = d; arrived = false;\n  store.set('dest', d);\n  store.set('destAt', Date.now());\n  M.setRoute(r.pts);\n  M.setDest(d);\n  wazePassedAlong=0;wazeLastPaintAlong=-Infinity;\n  wazeTrafficAt=0;wazeTrafficDestKey='';\n  paintWazeOverlay();\n  setTimeout(()=>refreshWazeRouteTraffic(true),100);\n  document.body.classList.add('navigating');\n  show($('search'), false); show($('banner'), true); show($('trip'), true);\n  if (sim) sim.along = 0;\n  if (pos) navUpdate();\n  else {\n    // No GPS fix yet: show the first turn and the whole trip until one arrives.\n    let j = 1;\n    while (j < r.steps.length - 1 && !important(r.steps[j])) j++;\n    const first = r.steps[Math.min(j, r.steps.length - 1)];\n    renderBanner(first, first.start, null);\n    renderTrip(r.total, r.duration);\n  }\n}\n\nfunction endRoute() {\n  route = null; dest = null; store.set('dest', null);\n  wazeRouteJams=[];wazePassedAlong=0;wazeLastPaintAlong=-Infinity;wazeTrafficAt=0;wazeTrafficDestKey='';paintWazeOverlay();\n  M.clearRoute(); M.clearDest();\n  document.body.classList.remove('navigating');\n  show($('search'), true); show($('banner'), false); show($('trip'), false);\n  if (sim) toggleSim();\n  if ('speechSynthesis' in window) speechSynthesis.cancel();\n  setFollow(true);\n}\n$('end').onclick = endRoute;\n\nlet overviewTimer;\nfunction overview(auto) {\n  if (!route) return;\n  setFollow(false);\n  M.fit(pos ? [...route.pts, pos] : route.pts, { top: 60, bottom: 60, left: 520, right: 120 });\n  clearTimeout(overviewTimer);\n  if (auto && pos) overviewTimer = setTimeout(() => { if (!follow) setFollow(true); }, 5000);\n}\n$('overview').onclick = () => overview(false);\n\n// ---------------------------------------------------------------- guidance\nfunction locate(r, p) {\n  const n = r.pts.length;\n  if (n < 2) return { i: 0, t: 0, d: dist(p, r.pts[0]), along: 0 };\n  const scan = (a, b) => {\n    let best = { i: a, t: 0, d: Infinity };\n    for (let i = a; i <= b; i++) {\n      const s = projSeg(p, r.pts[i], r.pts[i + 1]);\n      if (s.d < best.d) best = { i, t: s.t, d: s.d };\n    }\n    return best;\n  };\n  // Search near where we were last time; only fall back to the whole route when that fails,\n  // so a route that passes the same road twice doesn't make us jump ahead.\n  let best = scan(Math.max(0, r.hint - 3), Math.min(n - 2, r.hint + 150));\n  if (best.d > 60) { const all = scan(0, n - 2); if (all.d < best.d - 20) best = all; }\n  r.hint = best.i;\n  best.along = r.cum[best.i] + best.t * (r.cum[best.i + 1] - r.cum[best.i]);\n  return best;\n}\n\nfunction pointAt(r, along) {\n  let lo = 0, hi = r.cum.length - 1;\n  while (lo < hi - 1) { const mid = (lo + hi) >> 1; if (r.cum[mid] <= along) lo = mid; else hi = mid; }\n  const seg = r.cum[hi] - r.cum[lo], t = seg ? Math.min(1, Math.max(0, (along - r.cum[lo]) / seg)) : 0;\n  const a = r.pts[lo], b = r.pts[hi];\n  return { lat: a.lat + (b.lat - a.lat) * t, lng: a.lng + (b.lng - a.lng) * t, idx: lo };\n}\n\n/** Maneuvers worth a banner and a voice prompt; \"continue straight\" and name changes aren't. */\nfunction important(s) {\n  if (s.type === 'new name') return false;\n  if ((s.type === 'continue' || s.type === 'notification') && (s.mod === 'straight' || !s.mod)) return false;\n  return true;\n}\n\nfunction navUpdate() {\n  const r = route;\n  if (!r || !pos || arrived) return;\n  // Marks the trip as live, so a reload mid-drive resumes it but a later visit doesn't.\n  if (Date.now() - (store.get('destAt', 0) || 0) > 30_000) store.set('destAt', Date.now());\n  const loc = locate(r, pos);\n  wazePassedAlong=Math.max(wazePassedAlong,loc.along);\n  if(wazePassedAlong-wazeLastPaintAlong>=8){\n    wazeLastPaintAlong=wazePassedAlong;\n    paintWazeOverlay();\n  }\n\n  // Off route for three fixes in a row → ask for a new route (at most every 8 s).\n  const tolerance = Math.max(35, Math.min(80, (pos.acc || 10) * 1.5));\n  r.off = loc.d > tolerance ? r.off + 1 : 0;\n  if (r.off >= 3 && !routing && Date.now() - r.lastReroute > 8000) {\n    r.off = 0;\n    toast('Prepočítavam trasu…'); say('Prepočítavam trasu');\n    routeTo(dest, { reroute: true });\n  }\n\n  // Current step = last one whose maneuver we've passed; next = first important one after it.\n  let k = 0;\n  while (k + 1 < r.steps.length && r.steps[k + 1].start <= loc.along) k++;\n  let j = k + 1;\n  while (j < r.steps.length - 1 && !important(r.steps[j])) j++;\n  j = Math.min(j, r.steps.length - 1);\n  const next = r.steps[j], dNext = Math.max(0, next.start - loc.along);\n\n  let j2 = j + 1;\n  while (j2 < r.steps.length - 1 && !important(r.steps[j2])) j2++;\n  const then = j2 < r.steps.length && r.steps[j2].start - next.start < 250 ? r.steps[j2] : null;\n\n  renderBanner(next, dNext, then);\n  announce(j, next, dNext, then);\n\n  const remain = Math.max(0, r.total - loc.along);\n  const cur = r.steps[k], span = Math.max(1, cur.end - cur.start);\n  const secs = Math.max(0, (cur.end - loc.along) / span) * cur.dur + r.after[k];\n  renderTrip(remain, secs);\n\n  // Draw only the road still ahead.\n  M.setRoute([pos, ...r.pts.slice(loc.i + 1)]);\n\n  if (remain < 25 || (next.type === 'arrive' && dNext < 20 && loc.d < 50)) arrive();\n}\n\nfunction arrive() {\n  arrived = true;\n  store.set('dest', null);\n  say('Dorazili ste do cieľa' + (dest && dest.name && dest.name !== 'Označené miesto' ? ' ' + dest.name : ''));\n  toast('Dorazili ste do cieľa', 5000);\n  setTimeout(endRoute, 5000);\n}\n\nfunction renderBanner(s, d, then) {\n  $('bIcon').innerHTML = maneuverIcon(s);\n  $('bDist').textContent = s.type === 'arrive' && d < 30 ? 'Teraz' : fmtDist(d);\n  $('bText').textContent = s.text;\n  show($('bThen'), !!then);\n  if (then) $('bThen').innerHTML = 'Potom ' + maneuverIcon(then);\n}\n\nfunction renderTrip(remain, secs) {\n  const at = new Date(Date.now() + secs * 1000);\n  $('tArrive').textContent = at.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });\n  $('tRest').textContent = `${fmtDuration(secs)} · ${fmtDist(remain)}`;\n  const name = dest && dest.name ? String(dest.name).trim() : 'Cieľ';\n  $('tDest').textContent = '➡ ' + name;\n  const total = route && Number(route.total) > 0 ? Number(route.total) : remain;\n  const done = total > 0 ? Math.max(0, Math.min(1, 1 - remain / total)) : 0;\n  $('tripProgress').style.width = (done * 100).toFixed(1) + '%';\n}\n\n// ---------------------------------------------------------------- instructions\n/** Armenian → readable Latin for street names in instructions and speech (\"Վազգեն Սարգսյանի փողոց\" → \"Vazgen Sargsyani Poghots\"). */\nconst HY_READ = { 'ա':'a','բ':'b','գ':'g','դ':'d','ե':'e','զ':'z','է':'e','ը':'y','թ':'t','ժ':'zh','ի':'i','լ':'l','խ':'kh','ծ':'ts',\n  'կ':'k','հ':'h','ձ':'dz','ղ':'gh','ճ':'ch','մ':'m','յ':'y','ն':'n','շ':'sh','ո':'o','չ':'ch','պ':'p','ջ':'j','ռ':'r','ս':'s',\n  'վ':'v','տ':'t','ր':'r','ց':'ts','ւ':'v','փ':'p','ք':'k','և':'ev','օ':'o','ֆ':'f' };\nconst HY_TYPES = { 'փողոց': 'Street', 'պողոտա': 'Avenue', 'խճուղի': 'Highway', 'մայրուղի': 'Highway', 'նրբանցք': 'Lane',\n  'հրապարակ': 'Square', 'թաղամաս': 'District', 'փակուղի': 'Dead End', 'կամուրջ': 'Bridge', 'զբոսայգի': 'Park' };\nfunction readable(name) {\n  if (!name || !/[\\u0531-\\u0587]/.test(name)) return name;\n  // \"Սարգսյանի փողոց\" is \"Sargsyan's street\": drop the possessive -ի and translate the street word.\n  const parts = name.replace(/[\\u200b-\\u200f]/g, '').trim().split(/\\s+/);\n  const type = HY_TYPES[parts[parts.length - 1].toLowerCase()];\n  if (type) {\n    parts.pop();\n    // Not for \"Երևան-Գյումրի մայրուղի\": a road between two towns, and Gyumri really ends in -ի.\n    if (parts.length && !parts[parts.length - 1].includes('-')) parts[parts.length - 1] = parts[parts.length - 1].replace(/ի$/, '');\n  }\n  return parts.join(' ').split(/(\\s+|-)/).map(w => {\n    const lower = w.toLowerCase().replace(/ու/g, '\\u0000').replace(/^ե/, 'ye').replace(/^ո(?!\\u0000)/, 'vo');\n    const latin = lower.replace(/[\\u0561-\\u0587]/g, ch => HY_READ[ch] ?? ch).replace(/\\u0000/g, 'u');\n    return latin.charAt(0).toUpperCase() + latin.slice(1);\n  }).join('') + (type ? ' ' + type : '');\n}\n\nconst ordinal = n => n + (['th', 'st', 'nd', 'rd'][(n % 100 - 20) % 10] || ['th', 'st', 'nd', 'rd'][n % 100] || 'th');\nfunction side(mod) { return mod.includes('left') ? 'left' : mod.includes('right') ? 'right' : 'straight'; }\nfunction turnWord(mod) {\n  return { 'sharp left': 'Ostro odbočte doľava', left: 'Odbočte doľava', 'slight left': 'Mierne doľava',\n           'sharp right': 'Ostro odbočte doprava', right: 'Odbočte doprava', 'slight right': 'Mierne doprava',\n           straight: 'Pokračujte rovno', uturn: 'Otočte sa' }[mod] || 'Pokračujte';\n}\nfunction compass(b) { return ['na sever','na severovýchod','na východ','na juhovýchod','na juh','na juhozápad','na západ','na severozápad'][Math.round(b / 45) % 8]; }\n\nfunction instruction(s) {\n  const road = readable(s.name) || s.ref;\n  const onto = road ? ` na ${road}` : '';\n  switch (s.type) {\n    case 'depart': return `Pokračujte ${compass(s.bearingAfter || 0)}` + (road ? ` po ${road}` : '');\n    case 'arrive': return 'Dorazili ste do cieľa' + (s.mod === 'left' || s.mod === 'right' ? `, on the ${s.mod}` : '');\n    case 'roundabout': case 'rotary':\n      return s.exit ? `Na kruhovom objazde použite ${s.exit}. výjazd${onto}` : `Vojdite na kruhový objazd${onto}`;\n    case 'roundabout turn': return `Na kruhovom objazde ${turnWord(s.mod).toLowerCase()}${onto}`;\n    case 'exit roundabout': case 'exit rotary': return `Opustite kruhový objazd${onto}`;\n    case 'merge': return `Merge ${side(s.mod) === 'straight' ? '' : side(s.mod) + ' '}${onto.trim()}`.trim();\n    case 'on ramp': return `Take the ramp${side(s.mod) === 'straight' ? '' : ' on the ' + side(s.mod)}${onto}`;\n    case 'off ramp': return `Take the exit${side(s.mod) === 'straight' ? '' : ' on the ' + side(s.mod)}${onto}`;\n    case 'fork': return `Keep ${side(s.mod)} at the fork${onto}`;\n    case 'end of road': return `At the end of the road, turn ${side(s.mod)}${onto}`;\n    case 'new name': case 'continue':\n      if (s.mod === 'uturn') return 'Otočte sa' + onto;\n      if (!s.mod || s.mod === 'straight') return `Continue${onto}`;\n      return `Keep ${side(s.mod)}${onto}`;\n    default: return turnWord(s.mod) + onto;\n  }\n}\n\nfunction maneuverIcon(s) {\n  const stroke = 'fill=\"none\" stroke=\"currentColor\" stroke-width=\"5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"';\n  if (s.type === 'arrive') {\n    return `<svg viewBox=\"0 0 48 48\" ${stroke}><path d=\"M14 44V5\"/><path d=\"M14 7h22l-5 7 5 7H14\" fill=\"currentColor\"/></svg>`;\n  }\n  if (s.mod === 'uturn') {\n    return `<svg viewBox=\"0 0 48 48\" ${stroke}><path d=\"M32 44V20a9 9 0 0 0-18 0v10\"/><path d=\"M7 24l7 8 7-8\"/></svg>`;\n  }\n  const angle = { 'sharp left': -135, left: -90, 'slight left': -45, straight: 0, 'slight right': 45, right: 90, 'sharp right': 135 }[s.mod] ?? 0;\n  if (/roundabout|rotary/.test(s.type)) {\n    // Ring with the exit number inside, entry from below, exit arrow leaving the ring.\n    const num = s.exit ? `<text x=\"24\" y=\"29\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,sans-serif\">${s.exit}</text>` : '';\n    return `<svg viewBox=\"0 0 48 48\" ${stroke}><circle cx=\"24\" cy=\"24\" r=\"11\"/>${num}<path d=\"M24 46V35\"/>` +\n           `<g transform=\"rotate(${angle} 24 24)\"><path d=\"M24 13V4\"/><path d=\"M17 10l7-7 7 7\"/></g></svg>`;\n  }\n  return `<svg viewBox=\"0 0 48 48\" ${stroke}><path d=\"M24 45V24\"/>` +\n         `<g transform=\"rotate(${angle} 24 24)\"><path d=\"M24 24V5\"/><path d=\"M15 13l9-9 9 9\"/></g></svg>`;\n}\n\n// ---------------------------------------------------------------- voice\n// Tesla: keep navigation prompts inside one persistent Web Audio context.\n// A separate HTMLAudioElement or speechSynthesis can take/release media focus and make the car\n// resume radio after a prompt. Web Audio stays in the browser audio path used alongside Music.\nconst VoiceAudioContext = window.AudioContext || window.webkitAudioContext;\nlet voiceCtx = null, voiceGain = null, voiceSource = null, voiceKeepAlive = null, voiceSeq = 0;\n\nfunction ensureVoiceContext() {\n  if (!VoiceAudioContext) return null;\n  if (!voiceCtx) {\n    try {\n      voiceCtx = new VoiceAudioContext({ latencyHint: 'interactive' });\n      voiceGain = voiceCtx.createGain();\n      voiceGain.gain.value = voiceVolume;\n      voiceGain.connect(voiceCtx.destination);\n\n      // Silent continuous source: keeps the browser's audio path alive while navigation voice\n      // is enabled, so Tesla does not fall back to the previous radio source between prompts.\n      if (voiceCtx.createConstantSource) {\n        voiceKeepAlive = voiceCtx.createConstantSource();\n        voiceKeepAlive.offset.value = 0;\n        voiceKeepAlive.connect(voiceGain);\n        voiceKeepAlive.start();\n      } else {\n        const osc = voiceCtx.createOscillator();\n        const zero = voiceCtx.createGain();\n        zero.gain.value = 0;\n        osc.connect(zero);\n        zero.connect(voiceCtx.destination);\n        osc.start();\n        voiceKeepAlive = osc;\n      }\n    } catch {\n      voiceCtx = null; voiceGain = null; voiceKeepAlive = null;\n      return null;\n    }\n  }\n  if (voiceGain) voiceGain.gain.value = voiceVolume;\n  if (voiceCtx.state === 'suspended') {\n    try { voiceCtx.resume(); } catch {}\n  }\n  return voiceCtx;\n}\n\nfunction stopVoicePrompt() {\n  if (voiceSource) {\n    try { voiceSource.stop(); } catch {}\n    try { voiceSource.disconnect(); } catch {}\n    voiceSource = null;\n  }\n}\n\nfunction nativeSay(text) {\n  // Fallback only for browsers without Web Audio support.\n  if (VoiceAudioContext || !('speechSynthesis' in window) || typeof SpeechSynthesisUtterance === 'undefined') return false;\n  try {\n    speechSynthesis.cancel();\n    const u = new SpeechSynthesisUtterance(text);\n    u.lang = 'sk-SK';\n    u.rate = 1.0;\n    u.volume = voiceVolume;\n    const voices = speechSynthesis.getVoices ? speechSynthesis.getVoices() : [];\n    const sk = voices.find(v => /^sk([-_]|$)/i.test(v.lang || ''));\n    if (sk) u.voice = sk;\n    speechSynthesis.speak(u);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\nasync function say(text) {\n  if (!voiceOn || mode === 'mirror') return;\n  const clean = String(text || '').trim();\n  if (!clean) return;\n  const seq = ++voiceSeq;\n  stopVoicePrompt();\n\n  const ctx = ensureVoiceContext();\n  if (!ctx) return nativeSay(clean);\n\n  try {\n    const r = await fetch('/api/tts?text=' + encodeURIComponent(clean), { cache: 'force-cache' });\n    if (!r.ok) throw new Error('tts');\n    const bytes = await r.arrayBuffer();\n    if (seq !== voiceSeq || !voiceOn) return;\n    const buffer = await ctx.decodeAudioData(bytes.slice(0));\n    if (seq !== voiceSeq || !voiceOn) return;\n    const src = ctx.createBufferSource();\n    src.buffer = buffer;\n    src.connect(voiceGain);\n    src.onended = () => { if (voiceSource === src) voiceSource = null; };\n    voiceSource = src;\n    if (ctx.state === 'suspended') await ctx.resume();\n    src.start(0);\n  } catch {\n    if (seq === voiceSeq) nativeSay(clean);\n  }\n}\n\n// Unlock Web Audio from a real user gesture, but do not start speechSynthesis or another\n// media element. If voice is enabled, keep this context alive for the whole drive.\ndocument.addEventListener('pointerdown', () => {\n  if (voiceOn) ensureVoiceContext();\n}, { once: true });\n/** Up to three prompts per maneuver: early, near, and now; distances scale with speed. */\nfunction announce(j, s, d, then) {\n  const v = Math.max(pos.speed || 0, 8);\n  const nowD = Math.max(25, v * 3), nearD = Math.max(150, v * 11), farD = v > 22 ? 1500 : v > 14 ? 1000 : 600;\n  const a = route.ann[j] || (route.ann[j] = { first: d });\n  const lower = t => t.charAt(0).toLowerCase() + t.slice(1);\n  const thenText = then ? `, potom ${lower(then.text)}` : '';\n  if (!a.now && d <= nowD) {\n    a.now = a.near = a.far = true;\n    if (s.type !== 'arrive') say(s.text + thenText);\n  } else if (!a.near && d <= nearD) {\n    a.near = a.far = true;\n    say(`O ${spokenDist(d)} ${lower(s.text)}`);\n  } else if (!a.far && d <= farD && a.first > nearD + 300) {\n    a.far = true;\n    say(`O ${spokenDist(d)} ${lower(s.text)}`);\n  }\n}\n\nfunction renderVoice() {\n  $('voiceBtn').textContent = voiceOn ? '🔊  Hlas zapnutý' : '🔇  Hlas vypnutý';\n  const pct = Math.round(voiceVolume * 100);\n  $('voiceVolume').value = String(pct);\n  $('voiceVolumeValue').textContent = pct + ' %';\n}\n$('voiceBtn').onclick = () => {\n  voiceOn = !voiceOn;\n  store.set('voice', voiceOn);\n  ++voiceSeq;\n  stopVoicePrompt();\n  if (voiceOn) {\n    ensureVoiceContext();\n  } else {\n    if (voiceCtx && voiceCtx.state === 'running') {\n      try { voiceCtx.suspend(); } catch {}\n    }\n    if ('speechSynthesis' in window) try { speechSynthesis.cancel(); } catch {}\n  }\n  renderVoice();\n};\n$('voiceVolume').oninput = e => {\n  voiceVolume = Math.max(.2, Math.min(1, Number(e.target.value) / 100));\n  if (voiceGain) voiceGain.gain.value = voiceVolume;\n  store.set('voiceVolume', voiceVolume);\n  $('voiceVolumeValue').textContent = Math.round(voiceVolume * 100) + ' %';\n};\n$('voiceVolume').onchange = () => {\n  const was = voiceOn;\n  voiceOn = true;\n  say('Hlasitosť navigácie');\n  voiceOn = was;\n};\n$('testVoice').onclick = () => {\n  const was = voiceOn;\n  voiceOn = true;\n  toast('Prehrávam test slovenského hlasu…', 2500);\n  say('O tristo metrov odbočte doprava');\n  voiceOn = was;\n};\nrenderVoice();\n\n// ---------------------------------------------------------------- menu + simulator\n$('menuBtn').onclick = () => $('menu').classList.toggle('hidden');\nconst SIZES = [['Malé', .7], ['Stredné', .8], ['Veľké', .92]];\nlet sizeIndex = Math.max(0, SIZES.findIndex(([name]) => name === store.get('textSize', 'Stredné')));\nfunction applySize() { document.documentElement.style.setProperty('--ui', SIZES[sizeIndex][1]); }\napplySize();\n$('sizeBtn').onclick = () => { sizeIndex = (sizeIndex + 1) % SIZES.length; store.set('textSize', SIZES[sizeIndex][0]); applySize(); renderMenu(); };\n\nfunction renderMenu() {\n  $('sizeBtn').textContent = '🔠  Veľkosť textu: ' + SIZES[sizeIndex][0];\n  $('styleBtn').textContent = '🗺  Mapa: ' + M.styleName();\n  $('engineBtn').textContent = M.kind === 'vector' ? '🧭  Prepnúť na klasickú mapu' : '🧭  Prepnúť na vektorovú mapu';\n}\n$('styleBtn').onclick = () => { M.nextStyle(); renderMenu(); };\n$('engineBtn').onclick = () => { store.set('engine', M.kind === 'vector' ? 'classic' : 'vector'); location.reload(); };\nrenderMenu();\n\n// ---------------------------------------------------------------- chargers\n// EV charging stations (data/am-chargers.json: OpenStreetMap, plus Open Charge Map when the\n// index is built with a key). The ⚡ panel lists them nearest first with connector and\n// operator filters; the map shows the ones that pass the filters.\nlet chargersOn = store.get('chargers', false), chargerList = null;\nlet chargerFilter = store.get('chargerFilter', { conn: '', op: '', unknown: false, power: 0 });\nlet bigOperators = new Set();   // operators with 2+ stations get their own chip; the rest are \"Other\"\nconst CONNECTORS = ['CCS2', 'Type 2', 'CHAdeMO', 'GB/T', 'GB/T DC', 'Tesla'];\nconst SOCKET = { type2: 'Type 2', type2_combo: 'CCS2', chademo: 'CHAdeMO', gb_t: 'GB/T', gb_t_dc: 'GB/T DC', gb_ac: 'GB/T',\n                 type1: 'Type 1', type1_combo: 'CCS1', tesla_supercharger: 'Tesla', schuko: 'Socket' };\n\nasync function loadChargers() {\n  if (chargerList) return chargerList;\n  toast('Načítavam nabíjačky…', 8000);\n  const here = pos || M.center();\n  const url = new URL('/api/chargers', location.origin);\n  if (here && Number.isFinite(here.lat) && Number.isFinite(here.lng)) {\n    url.searchParams.set('lat', here.lat);\n    url.searchParams.set('lng', here.lng);\n  }\n  const r = await fetch(url, { cache: 'no-store' });\n  if (!r.ok) throw new Error('HTTP ' + r.status);\n  const d = await r.json();\n  if (!d || !Array.isArray(d.chargers)) throw new Error('Neplatné dáta');\n\n  const connectorLabel = t => ({\n    'CCS (Type 2)': 'CCS2',\n    'CCS (Type 1)': 'CCS1',\n    'CCS': 'CCS2',\n    'Type 2 (Tethered Connector) ': 'Type 2 (kábel)',\n    'Type 2 (Socket Only)': 'Type 2 (zásuvka)',\n    'Type 2': 'Type 2',\n    'Typ 2': 'Type 2',\n    'Type 1 (J1772)': 'Type 1',\n    'CHAdeMO': 'CHAdeMO',\n    'Tesla (Model S/X)': 'Tesla',\n    'Tesla Supercharger': 'Tesla Supercharger'\n  }[t] || t);\n\n  chargerList = d.chargers.map(x => {\n    const conns = x.c || [];\n    const maxKW = Number(x.maxKW) || conns.reduce((m,c) => Math.max(m, Number(c.kw)||0), 0);\n    const op = (!x.op || x.op === '(Unknown Operator)') ? '' : x.op;\n    return {\n      n: x.n || 'Nabíjacia stanica',\n      o: op,\n      p: maxKW ? maxKW + ' kW' : '',\n      c: x.points || 0,\n      s: [...new Set(conns.map(c => connectorLabel(c.t)).filter(Boolean))],\n      lat: x.lat,\n      lng: x.lng,\n      ll: [Math.round(x.lat * 1e5), Math.round(x.lng * 1e5)],\n      town: x.town || '',\n      addr: x.addr || '',\n      ocmId: x.id,\n      live: !!x.live,\n      stationId: x.stationId || null,\n      available: Number.isFinite(x.available) ? x.available : null,\n      total: Number.isFinite(x.total) ? x.total : null,\n      unknown: Number.isFinite(x.unknown) ? x.unknown : null,\n      liveSource: x.liveSource || ''\n    };\n  });\n\n  const counts = {};\n  chargerList.forEach(c => { if (c.o) counts[c.o] = (counts[c.o] || 0) + 1; });\n  bigOperators = new Set(Object.keys(counts).filter(o => counts[o] >= 2));\n  const liveCount = chargerList.filter(c => c.live).length;\n  toast('Načítaných ' + chargerList.length + ' lokalít' + (liveCount ? ' · ' + liveCount + ' s live stavom' : ''), 3500);\n  return chargerList;\n}\nconst opOf = c => bigOperators.has(c.o) ? c.o : 'Ostatní';\nfunction passes(c, f = chargerFilter) {\n  if ((f.power || 0) && (parseFloat(c.p) || 0) < f.power) return false;\n  if (f.op && opOf(c) !== f.op) return false;\n  if (!f.conn) return true;\n  if (!c.s.length) return f.unknown;          // no connector data: shown only when asked\n  return c.s.includes(f.conn) || (f.conn === 'GB/T' && c.s.includes('GB/T DC'));\n}\n\nfunction connBadges(c) {\n  return c.s.length ? c.s.map(k => `<span class=\"conn\">${esc(k)}</span>`).join('')\n                    : '<span class=\"conn unknown\">Konektory nie sú uvedené</span>';\n}\n\nfunction liveSummary(c) {\n  if (!c.live || c.available == null || c.total == null) return '';\n  const busy = Math.max(0, c.total - c.available - (c.unknown || 0));\n  return `<div class=\"liveStatus\"><b>Živá dostupnosť</b><br>\n    <span class=\"ok\">${c.available} z ${c.total} voľných</span>\n    ${busy ? ` · <span class=\"busy\">${busy} obsadené</span>` : ''}\n    ${c.unknown ? ` · <span class=\"muted\">${c.unknown} neznáme</span>` : ''}\n    <div class=\"muted\" style=\"margin-top:3px\">${esc(c.liveSource || 'Live')}</div>\n  </div>`;\n}\n\nasync function loadLiveDetail(c, holder) {\n  if (!c.stationId) return;\n  try {\n    const r = await fetch('/api/availability?stationId=' + encodeURIComponent(c.stationId), { cache: 'no-store' });\n    if (!r.ok) return;\n    const d = await r.json();\n    if (!d || !Array.isArray(d.points)) return;\n    const counts = d.points.reduce((m,p) => (m[p.status]=(m[p.status]||0)+1,m), {});\n    const labels = {\n      AVAILABLE:'Voľné',\n      OCCUPIED:'Obsadené',\n      CHARGING:'Nabíja',\n      OUT_OF_SERVICE:'Mimo prevádzky',\n      UNAVAILABLE:'Nedostupné',\n      UNSPECIFIED:'Neznáme',\n      UNKNOWN:'Neznáme'\n    };\n    holder.innerHTML = '<b>Realtime stav</b><br>' + Object.entries(counts)\n      .map(([k,v]) => esc((labels[k] || k) + ': ' + v)).join(' · ') +\n      (d.updatedAt ? '<div class=\"muted\" style=\"margin-top:3px\">Aktualizované: ' + esc(d.updatedAt) + '</div>' : '');\n  } catch {}\n}\n\nfunction showCharger(c) {\n  const el = document.createElement('div');\n  el.style.cssText = 'min-width:260px;font-size:16px';\n  el.innerHTML = `<b>${esc(c.n)}</b><div style=\"color:var(--quiet);margin:4px 0 2px\">${esc([c.o, c.p, c.c && c.c + ' bodov'].filter(Boolean).join(' · '))}</div>\n    <div style=\"margin-bottom:8px\">${connBadges(c)}</div>\n    ${liveSummary(c)}`;\n  if (c.stationId) {\n    const detail = document.createElement('div');\n    detail.className = 'liveStatus';\n    detail.innerHTML = '<span class=\"muted\">Načítavam realtime detail…</span>';\n    el.appendChild(detail);\n    loadLiveDetail(c, detail);\n  }\n  const row = document.createElement('div');\n  row.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap';\n  const go = document.createElement('button');\n  go.className = 'primary'; go.textContent = 'Navigovať sem';\n  go.onclick = () => { M.closePopup(); show($('chargerPanel'), false); routeTo({ lat: c.lat, lng: c.lng, name: c.n }); };\n  const report = document.createElement('button');\n  report.textContent = c.s.length ? 'Opraviť konektory' : 'Doplniť údaje o konektoroch';\n  report.onclick = () => reportCharger(c);\n  row.append(go, report);\n  el.appendChild(row);\n  M.popup(c, el);\n}\n\n// ---------------------------------------------------------------- report connectors\n// Drivers who see a charger can tell OpenStreetMap what it has: the page posts an anonymous\n// public OSM note at the station, volunteers add the tags, and the next index build picks\n// them up. No account needed. ?osmdev sends notes to OSM's test server instead.\nconst OSM_NOTES = params.has('osmdev') ? 'https://master.apis.dev.openstreetmap.org/api/0.6/notes.json'\n                                       : 'https://api.openstreetmap.org/api/0.6/notes.json';\nconst REPORT_SOCKETS = { 'CCS2': 'socket:type2_combo', 'Type 2': 'socket:type2', 'CHAdeMO': 'socket:chademo',\n                         'GB/T': 'socket:gb_t', 'GB/T DC': 'socket:gb_dc', 'Tesla': 'socket:tesla_supercharger' };\nconst REPORT_POWER = ['7 kW', '11 kW', '22 kW', '50 kW', '60 kW', '120 kW', '150+ kW'];\n\nfunction reportCharger(c) {\n  const key = `${c.ll[0]},${c.ll[1]}`;\n  const picked = new Set(c.s.filter(k => REPORT_SOCKETS[k]));\n  let power = '';\n  const el = document.createElement('div');\n  el.style.cssText = 'width:320px;font-size:16px';\n  el.innerHTML = `<b>Aké konektory má ${esc(c.n)}?</b>\n    <div style=\"color:var(--quiet);font-size:14px;margin:4px 0 10px\">Odošle sa verejná poznámka do OpenStreetMap, ktorú môžu dobrovoľníci doplniť do mapy.</div>\n    <div class=\"chipLabel\">Konektory</div><div class=\"rc\" style=\"display:flex;flex-wrap:wrap;gap:8px;margin:6px 0 12px\"></div>\n    <div class=\"chipLabel\">Najvyšší výkon (ak je uvedený)</div><div class=\"rp\" style=\"display:flex;flex-wrap:wrap;gap:8px;margin:6px 0 14px\"></div>`;\n  const chip = (box, label, on, toggle) => {\n    const b = document.createElement('button');\n    b.className = 'chip' + (on ? ' on' : ''); b.textContent = label;\n    b.onclick = () => { toggle(b); b.classList.toggle('on'); };\n    box.appendChild(b); return b;\n  };\n  for (const k of Object.keys(REPORT_SOCKETS)) chip(el.querySelector('.rc'), k, picked.has(k), () => picked.has(k) ? picked.delete(k) : picked.add(k));\n  const powerChips = REPORT_POWER.map(p => chip(el.querySelector('.rp'), p, false, tapped => {\n    power = power === p ? '' : p;\n    powerChips.forEach(b => b !== tapped && b.classList.remove('on'));   // one power at most\n  }));\n  const send = document.createElement('button');\n  send.className = 'primary'; send.textContent = 'Odoslať';\n  send.onclick = async () => {\n    if (!picked.size) return toast('Vyberte aspoň jeden konektor');\n    if (store.get('reported', []).includes(key)) return toast('Túto nabíjačku ste už nahlásili — ďakujeme!');\n    const tags = [...picked].map(k => `${REPORT_SOCKETS[k]}=yes`).concat(power ? [`charging_station:output=${power.replace('+', '')}`] : []);\n    const text = `EV charging station — connectors reported by a driver (HotspotNav car page)\\n\\n` +\n      `Station: ${c.n}${c.o ? ' (' + c.o + ')' : ''}\\nConnectors: ${[...picked].join(', ')}\\n` +\n      (power ? `Fastest charging: ${power}\\n` : '') + `Suggested tags: ${tags.join('; ')}\\n\\n#HotspotNav #evcharging`;\n    send.disabled = true; send.textContent = 'Odosielam…';\n    try {\n      const url = `${OSM_NOTES}?lat=${c.lat.toFixed(6)}&lon=${c.lng.toFixed(6)}&text=${encodeURIComponent(text)}`;\n      const ctl = new AbortController();\n      const timer = setTimeout(() => ctl.abort(), 15000);\n      const r = await fetch(url, { method: 'POST', signal: ctl.signal }).finally(() => clearTimeout(timer));\n      if (!r.ok) throw new Error(r.status);\n      store.set('reported', [...store.get('reported', []), key].slice(-200));\n      M.closePopup();\n      toast('Ďakujeme! Hlásenie bolo odoslané do OpenStreetMap.', 5000);\n    } catch {\n      send.disabled = false; send.textContent = 'Odoslať';\n      toast('Nepodarilo sa odoslať — nie je internet?');\n    }\n  };\n  const cancel = document.createElement('button');\n  cancel.textContent = 'Zrušiť'; cancel.onclick = () => showCharger(c);\n  const row = document.createElement('div');\n  row.style.cssText = 'display:flex;gap:8px'; row.append(send, cancel);\n  el.appendChild(row);\n  M.popup(c, el);\n}\n\nasync function renderChargers() {\n  $('chargerMapBtn').textContent = chargersOn ? 'Skryť na mape' : 'Zobraziť na mape';\n  const panelOpen = !$('chargerPanel').classList.contains('hidden');\n  if (!chargersOn && !panelOpen) return M.setChargers([], showCharger);\n  try {\n    const list = await loadChargers();\n    M.setChargers(list.filter(c => passes(c)), showCharger);\n    if (panelOpen) renderChargerPanel(list);\n  } catch { toast('Nepodarilo sa načítať nabíjačky'); }\n}\n\nfunction renderChargerPanel(list) {\n  const f = chargerFilter;\n  const chip = (label, on, onClick) => {\n    const b = document.createElement('button');\n    b.className = 'chip' + (on ? ' on' : ''); b.textContent = label; b.onclick = onClick;\n    return b;\n  };\n  const setF = patch => { chargerFilter = { ...chargerFilter, ...patch }; store.set('chargerFilter', chargerFilter); renderChargers(); };\n\n  // Connectors actually present, then operators by number of stations.\n  const conns = CONNECTORS.filter(k => list.some(c => c.s.includes(k)));\n  const ops = Object.entries(list.reduce((m, c) => (m[opOf(c)] = (m[opOf(c)] || 0) + 1, m), {}))\n    .sort((a, b) => (a[0] === 'Ostatní') - (b[0] === 'Ostatní') || b[1] - a[1]).map(([o]) => o);\n\n  const cc = $('connChips'); cc.innerHTML = '<div class=\"chipLabel\">Konektor</div>';\n  cc.append(chip('Všetky', !f.conn, () => setF({ conn: '' })), ...conns.map(k => chip(k, f.conn === k, () => setF({ conn: k }))));\n  if (f.conn) cc.append(chip('+ neuvedené', f.unknown, () => setF({ unknown: !f.unknown })));\n  const pc = $('powerChips'); pc.innerHTML = '<div class=\"chipLabel\">Výkon</div>';\n  const powerLevels = [\n    { v: 0, label: 'Všetky' },\n    { v: 50, label: '50+ kW' },\n    { v: 100, label: '100+ kW' },\n    { v: 150, label: '150+ kW' },\n    { v: 250, label: '250+ kW' }\n  ];\n  pc.append(...powerLevels.map(p => chip(p.label, (f.power || 0) === p.v, () => setF({ power: p.v }))));\n\n  const oc = $('opChips'); oc.innerHTML = '<div class=\"chipLabel\">Prevádzkovateľ</div>';\n  oc.append(chip('Všetci', !f.op, () => setF({ op: '' })), ...ops.map(o => chip(o, f.op === o, () => setF({ op: o }))));\n\n  const here = pos || M.center();\n  const shown = list.filter(c => passes(c)).sort((a, b) => dist(here, a) - dist(here, b));\n  const box = $('chargerList'); box.innerHTML = '';\n  if (!shown.length) {\n    const unknown = list.filter(c => !c.s.length && passes(c, { ...f, conn: '' })).length;\n    box.innerHTML = `<div class=\"res note\">Žiadna stanica zatiaľ neuvádza ${esc(f.conn || 'tento konektor')}${unknown && f.conn ? ` — ${unknown} nemá uvedené konektory; klepnite na „+ neuvedené“` : ''}.</div>`;\n  }\n  for (const c of shown) {\n    const div = document.createElement('div');\n    div.className = 'res';\n    div.innerHTML = `<b>⚡ ${esc(c.n)}</b><span>${esc([c.o, c.p, fmtDist(dist(here, c))].filter(Boolean).join(' · '))}</span>${c.live && c.available != null ? `<span style=\"color:#63d69a\">● ${c.available} z ${c.total} voľných</span>` : ''}<div>${connBadges(c)}</div>`;\n    div.onclick = () => { setFollow(false); M.jump(c, { zoom: 16 }); showCharger(c); };\n    box.appendChild(div);\n  }\n}\n\n$('chargersFab').onclick = () => {\n  const open = $('chargerPanel').classList.contains('hidden');\n  show($('chargerPanel'), open);\n  $('fabs').style.zIndex = open ? '900' : '1000';\n  show($('search'), !open && !route);\n  renderChargers();\n};\nfunction closeChargerPanel(e) {\n  if (e) { e.preventDefault(); e.stopPropagation(); }\n  show($('chargerPanel'), false);\n  show($('search'), !route);\n  renderChargers();\n}\n$('chargerClose').onclick = closeChargerPanel;\n$('chargerClose').addEventListener('pointerup', closeChargerPanel);\n$('chargerClose').addEventListener('touchend', closeChargerPanel, { passive: false });\n$('chargerMapBtn').onclick = () => { chargersOn = !chargersOn; store.set('chargers', chargersOn); renderChargers(); };\nrenderChargers();\n\n/** Drives the current route at 50 km/h — for testing at a desk or parked. */\nfunction toggleSim() {\n  if (sim) {\n    clearInterval(sim.timer); sim = null;\n    $('simBtn').textContent = 'Simulovať jazdu';\n    return;\n  }\n  if (!route) return toast('Najprv vyberte cieľ');\n  sim = { along: pos ? locate(route, pos).along : 0, speed: 14 };\n  $('simBtn').textContent = 'Zastaviť simuláciu';\n  $('menu').classList.add('hidden');\n  const tick = () => {\n    if (!route) return;\n    sim.along = Math.min(route.total, sim.along + sim.speed);\n    const p = pointAt(route, sim.along), ahead = pointAt(route, sim.along + 15);\n    onFix({ lat: p.lat, lng: p.lng, speed: sim.speed, course: bearing(p, ahead), acc: 5, ts: Date.now(), src: 'sim' });\n  };\n  tick();\n  sim.timer = setInterval(tick, 1000);\n}\n$('simBtn').onclick = toggleSim;\n\n// ---------------------------------------------------------------- hudba\nconst MUSIC_URL = 'https://music-mobile-307.onrender.com/?mobile=1';\nconst musicOverlay = $('musicOverlay');\nconst musicFrame = $('musicFrame');\nlet musicLoaded = false;\nlet musicStartY = null;\nlet musicDragging = false;\n\nfunction showMusic() {\n  if (!musicLoaded) {\n    musicFrame.src = MUSIC_URL;\n    musicLoaded = true;\n  }\n  musicOverlay.classList.add('open');\n  musicOverlay.setAttribute('aria-hidden', 'false');\n}\n\nfunction hideMusic() {\n  musicOverlay.classList.remove('open');\n  musicOverlay.setAttribute('aria-hidden', 'true');\n  // iframe sa zámerne neruší ani nenačítava nanovo\n}\n\n$('musicBtn').onclick = showMusic;\n\n$('musicGrab').addEventListener('pointerdown', e => {\n  musicStartY = e.clientY;\n  musicDragging = true;\n  try { $('musicGrab').setPointerCapture(e.pointerId); } catch {}\n});\n$('musicGrab').addEventListener('pointerup', e => {\n  if (!musicDragging || musicStartY == null) return;\n  const dy = e.clientY - musicStartY;\n  musicDragging = false;\n  musicStartY = null;\n  if (dy > 45) hideMusic();\n});\n$('musicGrab').addEventListener('pointercancel', () => {\n  musicDragging = false;\n  musicStartY = null;\n});\n\n// iOS/Tesla browser fallback pre dotykové gestá\nlet musicTouchY = null;\n$('musicGrab').addEventListener('touchstart', e => {\n  musicTouchY = e.touches && e.touches[0] ? e.touches[0].clientY : null;\n}, { passive: true });\n$('musicGrab').addEventListener('touchend', e => {\n  if (musicTouchY == null) return;\n  const y = e.changedTouches && e.changedTouches[0] ? e.changedTouches[0].clientY : musicTouchY;\n  const dy = y - musicTouchY;\n  musicTouchY = null;\n  if (dy > 45) hideMusic();\n}, { passive: true });\n\n// ---------------------------------------------------------------- Waze / CarPlay overlay\nconst WAZE_URL = 'https://tesla-waze.vercel.app/';\nconst wazeOverlay = $('wazeOverlay');\nconst wazeFrame = $('wazeFrame');\nlet wazeLoaded = false;\nlet wazeStartY = null;\nlet wazeDragging = false;\n\nfunction showWazeApp() {\n  // Music stays loaded but is hidden so only one full-screen overlay is visible.\n  hideMusic();\n  if (!wazeLoaded) {\n    wazeFrame.src = WAZE_URL;\n    wazeLoaded = true;\n  }\n  wazeOverlay.classList.add('open');\n  wazeOverlay.setAttribute('aria-hidden', 'false');\n}\n\nfunction hideWazeApp() {\n  wazeOverlay.classList.remove('open');\n  wazeOverlay.setAttribute('aria-hidden', 'true');\n  // iframe sa zámerne neruší ani nenačítava nanovo\n}\n\n$('wazeBtn').onclick = showWazeApp;\n\n$('wazeGrab').addEventListener('pointerdown', e => {\n  wazeStartY = e.clientY;\n  wazeDragging = true;\n  try { $('wazeGrab').setPointerCapture(e.pointerId); } catch {}\n});\n$('wazeGrab').addEventListener('pointerup', e => {\n  if (!wazeDragging || wazeStartY == null) return;\n  const dy = e.clientY - wazeStartY;\n  wazeDragging = false;\n  wazeStartY = null;\n  if (dy > 45) hideWazeApp();\n});\n$('wazeGrab').addEventListener('pointercancel', () => {\n  wazeDragging = false;\n  wazeStartY = null;\n});\n\nlet wazeTouchY = null;\n$('wazeGrab').addEventListener('touchstart', e => {\n  wazeTouchY = e.touches && e.touches[0] ? e.touches[0].clientY : null;\n}, { passive: true });\n$('wazeGrab').addEventListener('touchend', e => {\n  if (wazeTouchY == null) return;\n  const y = e.changedTouches && e.changedTouches[0] ? e.changedTouches[0].clientY : wazeTouchY;\n  const dy = y - wazeTouchY;\n  wazeTouchY = null;\n  if (dy > 45) hideWazeApp();\n}, { passive: true });\n\n// ---------------------------------------------------------------- mirror mode\n// The car's browser refuses private addresses, so the iPhone can't serve its screen over the\n// hotspot. Instead the broadcast extension sends H.264 video (or JPEGs) through a small\n// Cloudflare relay; this page decodes it with WebCodecs and draws it on a canvas.\n//\n// Binary messages: [kind:1][timestamp ms:4 BE][payload]  kind 1 = key frame, 2 = delta\n// frame (both Annex B H.264), 3 = JPEG. Text messages are small JSON control messages.\nconst RELAY = 'wss://tesla-hotspotnav-relay-test.onrender.com/ws';\nconst canvas = $('mirrorCanvas'), ctx = canvas.getContext('2d');\nlet ws = null, decoder = null, reconnectTimer = null;\nlet rotation = 0, needKey = true, gotFrame = false, phoneOnline = false, decoderCodec = '';\nconst wantsH264 = 'VideoDecoder' in window && 'EncodedVideoChunk' in window;\n\nconst pairCode = () => store.get('pair', '');\n\nfunction mirrorHint(title) {\n  show($('mirrorHint'), !!title);\n  if (title) $('mirrorHintTitle').textContent = title;\n}\n\nfunction setMode(m) {\n  if (m === 'mirror' && !pairCode()) return askPair(() => setMode('mirror'));\n  mode = m;\n  store.set('mode', m);\n  show($('mirror'), m === 'mirror');\n  if (m === 'mirror') {\n    if ('speechSynthesis' in window) speechSynthesis.cancel();\n    gotFrame = false;\n    mirrorHint('Pripájam…');\n    mirrorConnect();\n  } else {\n    mirrorDisconnect();\n    if (follow) followCar();\n  }\n}\n\nfunction mirrorConnect() {\n  mirrorDisconnect();\n  const sock = new WebSocket(`${RELAY}?room=${encodeURIComponent(pairCode())}&role=car`);\n  sock.binaryType = 'arraybuffer';\n  sock.onopen = () => sock.send(JSON.stringify({ type: 'want', format: wantsH264 ? 'h264' : 'jpeg' }));\n  sock.onmessage = e => typeof e.data === 'string' ? onControl(JSON.parse(e.data)) : onMedia(e.data);\n  sock.onclose = () => {\n    if (ws !== sock) return;\n    ws = null;\n    if (mode === 'mirror') {\n      mirrorHint('Obnovujem spojenie…');\n      reconnectTimer = setTimeout(mirrorConnect, 2000);\n    }\n  };\n  ws = sock;\n}\n\nfunction mirrorDisconnect() {\n  clearTimeout(reconnectTimer);\n  if (ws) { const old = ws; ws = null; old.close(); }\n  if (decoder) { try { decoder.close(); } catch {} decoder = null; }\n  decoderCodec = '';\n  needKey = true;\n}\n\nfunction send(obj) { if (ws && ws.readyState === 1) ws.send(JSON.stringify(obj)); }\n\nfunction onControl(msg) {\n  if (msg.type === 'phone') {\n    phoneOnline = msg.online;\n    if (!msg.online) { gotFrame = false; mirrorHint('Čakám na iPhone…'); }\n    else if (!gotFrame) mirrorHint('iPhone pripojený — čakám na obraz…');\n  } else if (msg.type === 'config') {\n    // A rotation-only update must not reset the decoder (that would ask for a key frame,\n    // and the phone answers key-frame requests with fresh frames, not a new config).\n    rotation = msg.rotation || 0;\n    if (wantsH264 && msg.codec && (msg.codec !== decoderCodec || !decoder)) configureDecoder(msg.codec);\n  }\n}\n\nasync function configureDecoder(codec) {\n  const config = { codec, optimizeForLatency: true };\n  try {\n    const { supported } = await VideoDecoder.isConfigSupported(config);\n    if (!supported) throw new Error('unsupported');\n  } catch {\n    // This browser can't decode the stream: ask the phone for JPEGs instead.\n    return send({ type: 'want', format: 'jpeg' });\n  }\n  if (decoder) { try { decoder.close(); } catch {} }\n  decoder = new VideoDecoder({\n    output: frame => { draw(frame, frame.displayWidth, frame.displayHeight); frame.close(); },\n    error: () => { decoder = null; decoderCodec = ''; needKey = true; send({ type: 'keyframe' }); },\n  });\n  decoder.configure(config);\n  decoderCodec = codec;\n  needKey = true;\n  send({ type: 'keyframe' });\n}\n\nfunction onMedia(buf) {\n  const bytes = new Uint8Array(buf);\n  const kind = bytes[0];\n  const ts = new DataView(buf).getUint32(1);\n  const payload = bytes.subarray(5);\n  if (kind === 3) {\n    createImageBitmap(new Blob([payload], { type: 'image/jpeg' }))\n      .then(bmp => { draw(bmp, bmp.width, bmp.height); bmp.close(); })\n      .catch(() => {});\n    return;\n  }\n  if (!decoder || decoder.state !== 'configured') return;\n  if (needKey && kind !== 1) return;\n  // Falling behind: drop what's queued and start again from the next key frame.\n  if (decoder.decodeQueueSize > 6) { needKey = true; send({ type: 'keyframe' }); return; }\n  needKey = false;\n  try {\n    decoder.decode(new EncodedVideoChunk({ type: kind === 1 ? 'key' : 'delta', timestamp: ts * 1000, data: payload }));\n  } catch {\n    needKey = true; send({ type: 'keyframe' });\n  }\n}\n\n/** Draw a frame to fill the screen without cropping, honouring the phone's rotation. */\nfunction draw(src, w, h) {\n  const dpr = window.devicePixelRatio || 1;\n  const cw = Math.round(canvas.clientWidth * dpr), ch = Math.round(canvas.clientHeight * dpr);\n  if (canvas.width !== cw || canvas.height !== ch) { canvas.width = cw; canvas.height = ch; }\n  const turned = rotation === 90 || rotation === 270;\n  const sw = turned ? h : w, sh = turned ? w : h;\n  // Fit shows the whole phone screen; Fill covers the car screen and crops the overflow.\n  const scale = fill ? Math.max(cw / sw, ch / sh) : Math.min(cw / sw, ch / sh);\n  ctx.setTransform(1, 0, 0, 1, 0, 0);\n  ctx.fillStyle = '#000'; ctx.fillRect(0, 0, cw, ch);\n  ctx.translate(cw / 2, ch / 2);\n  ctx.rotate(rotation * Math.PI / 180);\n  ctx.drawImage(src, -w * scale / 2, -h * scale / 2, w * scale, h * scale);\n  if (!gotFrame) { gotFrame = true; mirrorHint(''); }\n}\n\nfunction freshPairCode() {\n  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';\n  let out = '';\n  if (window.crypto && crypto.getRandomValues) {\n    const a = new Uint8Array(8); crypto.getRandomValues(a);\n    for (const n of a) out += chars[n % chars.length];\n  } else {\n    for (let i = 0; i < 8; i++) out += chars[Math.floor(Math.random() * chars.length)];\n  }\n  store.set('pair', out);\n  navConnect();\n  return out;\n}\nfunction ensurePairCode() {\n  const old = String(pairCode() || '').replace(/[^A-Z0-9]/g, '');\n  return old.length === 8 ? old : freshPairCode();\n}\nfunction openMobilePair() {\n  $('menu').classList.add('hidden');\n  const code = ensurePairCode();\n  const pretty = code.slice(0,4) + '-' + code.slice(4);\n  const url = location.origin + '/phone.html?room=' + encodeURIComponent(code);\n  $('pairDisplay').textContent = pretty;\n  $('pairQr').src = 'https://api.qrserver.com/v1/create-qr-code/?size=420x420&margin=8&format=svg&data=' + encodeURIComponent(url);\n  show($('pair'), true);\n}\n$('pairCancel').onclick = () => show($('pair'), false);\n$('pairNew').onclick = () => { freshPairCode(); openMobilePair(); };\n$('pairBtn').onclick = openMobilePair;\n$('mirrorBtn').onclick = openMobilePair;\n$('mirrorBack').onclick = () => { if (document.fullscreenElement) document.exitFullscreen().catch(() => {}); setMode('map'); };\n\nlet fill = store.get('fill', false);\nfunction renderFit() { $('fitBtn').textContent = fill ? '⤡  Prispôsobiť' : '⤢  Vyplniť'; }\n$('fitBtn').onclick = () => { fill = !fill; store.set('fill', fill); renderFit(); canvas.width = 0; send({ type: 'keyframe' }); };\nrenderFit();\n\n// Celá obrazovka hides the car's side panel and the browser bar. Not every car browser allows it\n// (some only while parked); the car's own ⛶ button next to the address bar also helps.\n$('fullBtn').onclick = () => {\n  const el = $('mirror');\n  const req = el.requestFullscreen || el.webkitRequestFullscreen;\n  if (!req) return toast('Použite tlačidlo ⛶ vedľa adresného riadku');\n  Promise.resolve(req.call(el)).catch(() => toast('Celá obrazovka tu nie je povolená — skúste tlačidlo ⛶ vedľa adresného riadku'));\n};\ndocument.addEventListener('fullscreenchange', () => { canvas.width = 0; send({ type: 'keyframe' }); });\n\n// The buttons fade out after a few seconds so they don't cover the phone screen; tap to show.\nlet idleTimer;\nfunction wake() {\n  $('mirror').classList.remove('idle');\n  clearTimeout(idleTimer);\n  idleTimer = setTimeout(() => $('mirror').classList.add('idle'), 4000);\n}\n$('mirror').addEventListener('pointerdown', wake);\n$('mirrorBtn').addEventListener('click', wake);\nwindow.addEventListener('resize', () => { if (canvas.width) { canvas.width = 0; } });\n\n// ---------------------------------------------------------------- places from the phone\n// Share a place from Yandex Maps, Google Maps or Apple Maps on the iPhone (Share → HotspotNav)\n// and it arrives here through the relay. This socket only receives destinations, so it doesn't\n// count as watching the phone's screen (no video is sent for it).\nlet navSock = null, navRetry = null, navDelay = 2000;\nfunction navConnect() {\n  clearTimeout(navRetry);\n  if (navSock) { const old = navSock; navSock = null; old.close(); }\n  if (!pairCode()) return;\n  const sock = new WebSocket(`${RELAY}?room=${encodeURIComponent(pairCode())}&role=nav`);\n  sock.onopen = () => { navDelay = 2000; };\n  sock.onmessage = e => {\n    let m; try { m = JSON.parse(e.data); } catch { return; }\n    if (m.type === 'dest' && Number.isFinite(m.lat) && Number.isFinite(m.lng)) placeFromPhone(m);\n  };\n  sock.onclose = () => {\n    if (navSock !== sock) return;\n    navSock = null;\n    navRetry = setTimeout(navConnect, navDelay);\n    navDelay = Math.min(navDelay * 2, 60000);\n  };\n  navSock = sock;\n}\n\nfunction placeFromPhone(m) {\n  const name = m.name || 'Miesto z iPhonu';\n  const it = { name, detail: m.source ? 'z ' + m.source : 'z iPhonu', lat: m.lat, lng: m.lng };\n  if (mode === 'mirror') setMode('map');\n  $('menu').classList.add('hidden');\n  show($('chargerPanel'), false);\n  toast('📱 ' + name, 4000);\n  choose(it);\n}\n\n// ---------------------------------------------------------------- start\n// ?to=lat,lng[&name=…] opens straight into navigation (a shareable destination link);\n// adding &sim drives it with the simulator.\nconst to = (params.get('to') || '').split(',').map(Number);\ndest = to.length === 2 && to.every(Number.isFinite)\n  ? { lat: to[0], lng: to[1], name: params.get('name') || 'Cieľ' }\n  // Otherwise resume a trip only if the page reloaded mid-drive (the car browser does that);\n  // a trip left open from an earlier drive is dropped, so the map always opens without a route.\n  : (Date.now() - (store.get('destAt', 0) || 0) < 5 * 60_000 ? store.get('dest', null) : null);\nif (!dest) store.set('dest', null);\ndetectSource();\nstore.set('mode', 'map');\nmode = 'map';\nshow($('mirror'), false);\nnavConnect();\n// A ?to= link opened without a GPS fix (e.g. testing at a desk): route from the map centre.\nif (params.has('to') && dest) setTimeout(() => { if (!pos && !route) routeTo(dest); }, 3000);\n})();\n</script>\n</body>\n</html>\n";
module.exports=(req,res)=>{
  const expected=process.env.TESLA_APP_DEVICE_TOKEN||'';
  const cookie=String(req.headers.cookie||'');
  const m=cookie.match(/(?:^|;\s*)tesla_device=([^;]+)/);
  const token=m?decodeURIComponent(m[1]):'';
  if(!expected||token!==expected){
    res.statusCode=302;
    res.setHeader('Location','/auth.html');
    res.setHeader('Cache-Control','no-store');
    return res.end();
  }
  res.statusCode=200;
  res.setHeader('Content-Type','text/html; charset=utf-8');
  res.setHeader('Cache-Control','private, no-store');
  res.end(APP_HTML);
};